ProgramBlock.ScriptSource:
// ===================================================================
// CONTEXT ENGINE - SYSTEM UTILITY
// ===================================================================
// This service generates dynamic prompts for LLM handlers.
// It populates templates with the list of controllable devices and
// current system status (Weather, Energy, Security, and live states).
// ===================================================================

// Versioned context profile only: no system data is collected or sent by these endpoints.
Func<object, JObject> readContextProfile = input => {
    var request = Api.Parse(input);
    object body = request?.Data ?? input;
    if (body == null) return new JObject();
    if (body is byte[] bytes) body = Encoding.UTF8.GetString(bytes);
    if (body is string text) return string.IsNullOrWhiteSpace(text) ? new JObject() : JObject.Parse(text);
    return body as JObject ?? JObject.FromObject(body);
};
Api.Handle("System.Utility/ContextEngine/Context.Describe", input => ChatContextPolicy.Describe());
Api.Handle("System.Utility/ContextEngine/Context.Policy", input => {
    try { return ChatContextPolicy.Build(readContextProfile(input)); }
    catch (Exception ex) { return new { Status = "Error", Message = ex.Message }; }
});

// Shared catalog/composition only: no provider calls, data collection or action execution.
Func<AiSkillCatalog> skillCatalog = () => new AiSkillCatalog(HomeGenie.Service.Utility.GetDataFolder());
Api.Handle("System.Utility/ContextEngine/Skills.List", input => {
    try { return (object)skillCatalog().List(); }
    catch (Exception ex) { return new { Status = "Error", Message = ex.Message }; }
});
Api.Handle("System.Utility/ContextEngine/Prompt.Compose", input => {
    try { return (object)skillCatalog().Compose(readContextProfile(input)); }
    catch (Exception ex) { return new { Status = "Error", Message = ex.Message }; }
});

Api.Handle("System.Utility/ContextEngine/GetStatus", (args) => {
    var statusSb = new StringBuilder();

    var controlModules = new List<ModuleHelper>();
    var sensorModules = new List<ModuleHelper>();
    string allowedTypes = "Dimmer,Light,Color,Switch,Shutter,DoorLock,Thermostat,Sensor,DoorWindow";

    Modules.OfDeviceType(allowedTypes).Each((m) => {
        var instance = m.Instance;
        var deviceType = instance.DeviceType.ToString().ToLower();
        if ((deviceType == "sensor" || deviceType == "doorwindow") && instance.Domain != "HomeAutomation.SecuritySystem")
            sensorModules.Add(m);
        else
            controlModules.Add(m);
        return false;
    });

    var weather = Modules.InDomain("HomeAutomation.HomeGenie.Automation").WithAddress("34").Get();
    if (weather.Instance != null) statusSb.AppendLine("Weather: " + PromptHelpers.GetWeatherStatus(weather));

    var energy = Modules.InDomain("HomeAutomation.EnergyMonitor").WithAddress("1").Get();
    if (energy.Instance != null) statusSb.AppendLine("Energy: " + PromptHelpers.GetEnergyStatus(energy));

    var alarm = Modules.InDomain("HomeAutomation.SecuritySystem").WithAddress("Main").Get();
    if (alarm.Instance != null) statusSb.AppendLine("Alarm: " + PromptHelpers.GetSecurityStatus(alarm));

    statusSb.AppendLine("\nDEVICES STATUS:");
    foreach (var m in controlModules) {
        var info = PromptHelpers.GetModuleStatus(m);
        if (!string.IsNullOrEmpty(info)) statusSb.AppendLine(info);
    }

    foreach (var m in sensorModules) {
        var info = PromptHelpers.GetModuleStatus(m);
        if (!string.IsNullOrEmpty(info)) statusSb.AppendLine(info);
    }

    return statusSb.ToString();
});

Api.Handle("System.Utility/ContextEngine", (args) => {
    var request = Api.Parse(args);
    string template = (string)request.Data;

    if (string.IsNullOrEmpty(template))
    {
        template = "**AVAILABLE MODULES**\n\n%%AVAILABLE_DEVICES%%\n**CURRENT SYSTEM STATUS** (Timestamp: %%CURRENT_TIME%%)\n\n%%SYSTEM_STATUS%%\n";
    }

    // --- 1. COLLECT USER-CONFIGURED MODULES ---
    // We create a unified list of ModuleHelpers that the user is allowed to control.
    var controlModules = new List<ModuleHelper>();
    var sensorModules = new List<ModuleHelper>();

    // Physical devices (Lights, Switches, Thermostats, etc.)
    string allowedTypes = "Dimmer,Light,Color,Switch,Shutter,DoorLock,Thermostat,Sensor,DoorWindow";
    Modules.OfDeviceType(allowedTypes).Each((m) => {
        var instance = m.Instance;
        var deviceType = instance.DeviceType.ToString().ToLower();
        if ((deviceType == "sensor" || deviceType == "doorwindow") && instance.Domain != "HomeAutomation.SecuritySystem")
        {
            sensorModules.Add(m);
            // the only "Sensor" listed in 'controlModules' is Security Alarm System
        } else {
            controlModules.Add(m);
        }
        return false; // Continue iteration
    });

    // Scenarios and Macros (Programs configured with the generic program widget)
    Modules.OfDeviceType("Program").WithParameter("Widget.DisplayModule").Each((m) => {
        // Filter out system loggers and ensure it's a user-facing program
        var widget = m.Parameter("Widget.DisplayModule")?.Value;
        if (m.Instance.Address != "6" && m.Instance.Address != "7"
            && m.Instance.Address != "34" && m.Instance.Address != "940"
            && !String.IsNullOrWhiteSpace(widget))
        {
            controlModules.Add(m);
        }
        return false;
    });

    // --- 2. GENERATE AVAILABLE DEVICES LIST (Directory) ---
    // This section provides the AI with a clean list of IDs and types.
    // Live states (ON/OFF) are NOT included here to keep the list stable.
    var devicesSb = new StringBuilder();
    foreach (var m in controlModules) {
        var module = m.Instance;
        var type = module.DeviceType.ToString();
        // exception
        if (type == "Program" && m.Parameter("Widget.DisplayModule").Value != "homegenie/generic/program")
        {
            type = m.Parameter("Widget.DisplayModule").Value;
            if (type.LastIndexOf("/") > 0)
            {
                type = type.Substring(type.LastIndexOf("/") + 1);
            }
        }

        var moduleGroups = Modules.Groups
            .Where(g => Modules.InGroup(g).SelectedModules.Any(mod =>
                mod.Domain == module.Domain &&
                mod.Address == module.Address))
            .ToList();

        var groups = string.Join(", ", moduleGroups);
        if (string.IsNullOrEmpty(groups))
        {
            groups = "(unassigned)";
        }

        devicesSb.AppendLine($"- {module.Name} | {type} | {module.Domain}/{module.Address} | " + groups);
    }

    // --- 3. GENERATE SYSTEM STATUS REPORT (Live Context) ---
    // This section provides the AI with real-time situational awareness.
    var statusSb = new StringBuilder();

    // A. Core System Reports (Weather, Energy, Alarm, Master Thermostat)
    statusSb.AppendLine("## SYSTEM REPORT");

    var weather = Modules.InDomain("HomeAutomation.HomeGenie.Automation").WithAddress("34").Get();
    if (weather.Instance != null) statusSb.AppendLine("- " + PromptHelpers.GetWeatherStatus(weather));

    var energy = Modules.InDomain("HomeAutomation.EnergyMonitor").WithAddress("1").Get();
    if (energy.Instance != null) statusSb.AppendLine("- " + PromptHelpers.GetEnergyStatus(energy));

    var alarm = Modules.InDomain("HomeAutomation.SecuritySystem").WithAddress("Main").Get();
    if (alarm.Instance != null) statusSb.AppendLine("- " + PromptHelpers.GetSecurityStatus(alarm));

    var thermo = Modules.InDomain("HomeAutomation.SmartThermostat").WithAddress("1").Get();
    if (thermo.Instance != null) statusSb.AppendLine("- " + PromptHelpers.GetThermostatStatus(thermo));

    // B. Individual Devices Live Status
    // Provides a 1:1 status update for the devices listed in the directory.
    statusSb.AppendLine("\n## DEVICES STATUS");
    foreach (var m in controlModules) {
        var info = PromptHelpers.GetModuleStatus(m);
        if (!string.IsNullOrEmpty(info)) statusSb.AppendLine("- " + info);
    }
    statusSb.AppendLine("\n## SENSORS STATUS");
    foreach (var m in sensorModules) {
        var info = PromptHelpers.GetModuleStatus(m);
        if (!string.IsNullOrEmpty(info)) statusSb.AppendLine("- " + info);
    }

    // --- 4. TEMPLATE ASSEMBLY ---
    // Replace placeholders with generated content and current server time.
    return template
        .Replace("%%AVAILABLE_DEVICES%%", devicesSb.ToString())
        .Replace("%%SYSTEM_STATUS%%", statusSb.ToString())
        .Replace("%%CURRENT_TIME%%", DateTime.Now.ToString("f", System.Globalization.CultureInfo.InvariantCulture)
        + "\n--- END OF SYSTEM REPORT ---\n\n");
});

// Run in background to stay available for LLM handler requests
Program.GoBackground();

ProgramBlock.ScriptContext:
public static class PromptHelpers
{
    /**
     * Helper to format double values for the AI.
     * Ensures the dot is always used as the decimal separator (Invariant Culture).
     */
    public static string Fmt(double val, string unit = "")
    {
        if (double.IsNaN(val) || double.IsInfinity(val)) return "N/A";
        return val.ToString("F1", CultureInfo.InvariantCulture) + unit;
    }

    /**
     * Extracts weather conditions, exterior temperature, and wind speed.
     */
    public static string GetWeatherStatus(ModuleHelper m)
    {
        var condition = m.Parameter("Conditions.Status").Value;
        if (string.IsNullOrWhiteSpace(condition)) condition = m.Parameter("Conditions.Description").Value;

        var temp = Fmt(m.Parameter("Sensor.Temperature").DecimalValue, "°C");
        var wind = Fmt(m.Parameter("Sensor.Wind.Speed").DecimalValue, " Kph");

        return $"Weather: {(string.IsNullOrEmpty(condition) ? "Unknown" : condition)} | Exterior Temp: {temp} | Wind: {wind}";
    }

    /**
     * Summarizes energy load, daily usage, and active device counts.
     */
    public static string GetEnergyStatus(ModuleHelper m)
    {
        var load = Fmt(m.Parameter("EnergyMonitor.WattLoad").DecimalValue, "W");
        var todayKwh = (m.Parameter("EnergyMonitor.WattCounter.Today").DecimalValue / 1000.0).ToString("F2", CultureInfo.InvariantCulture) + " kWh";

        var lights = m.Parameter("EnergyMonitor.OperatingLights").Value;
        var appliances = m.Parameter("EnergyMonitor.OperatingSwitches").Value;

        return $"Energy: Load {load} | Today's Usage: {todayKwh} (Active -> Lights: {lights}, Appliances: {appliances})";
    }

    /**
     * Reports the alarm arming mode and whether the security system is currently triggered.
     */
    public static string GetSecurityStatus(ModuleHelper m)
    {
        var state = m.Parameter("HomeGenie.SecurityArmed").Value;
        var triggered = m.Parameter("HomeGenie.SecurityTriggered").DecimalValue > 0 ? " !!ALARM TRIGGERED!!" : "";

        return $"Security: System is {state}{triggered}";
    }

    /**
     * Reports ambient temperature, target setpoint, and the current operating state.
     */
    public static string GetThermostatStatus(ModuleHelper m)
    {
        var ambient = Fmt(m.Parameter("Sensor.Temperature").DecimalValue, "°C");
        var target = Fmt(m.Parameter("Thermostat.SetPoint.Heating").DecimalValue, "°C");
        var state = m.Parameter("Thermostat.OperatingState").Value;
        var mode = m.Parameter("Thermostat.Mode").Value;

        return $"Thermostat: Ambient {ambient} | Target {target} (Mode: {mode}, State: {state})";
    }

    /**
     * Extracts a concise status string for any module (Sensors, Actuators, or Programs).
     * Used for the dynamic System Update/Status report.
     */
    public static string GetModuleStatus(ModuleHelper m)
    {
        // Skip modules with no name to keep the prompt clean
        if (string.IsNullOrWhiteSpace(m.Instance.Name)) return "";

        var statusParts = new List<string>();

        // 1. PROGRAMS (Scenarios/Macros)
        if (m.Instance.DeviceType.ToString() == "Program")
        {
            var pStatus = m.Parameter("Program.Status").Value;
            statusParts.Add("Status: " + (string.IsNullOrEmpty(pStatus) ? "Idle" : pStatus));
        }

        // 2. SENSORS (Environmental parameters)
        if (m.HasParameter("Sensor.Temperature"))
            statusParts.Add("Temp: " + Fmt(m.Parameter("Sensor.Temperature").DecimalValue, "°C"));

        if (m.HasParameter("Sensor.Humidity"))
            statusParts.Add("Hum: " + Fmt(m.Parameter("Sensor.Humidity").DecimalValue, "%"));

        if (m.HasParameter("Sensor.Luminance"))
            statusParts.Add("Luminance: " + m.Parameter("Sensor.Luminance").Value + " lux");

        if (m.HasParameter("Sensor.Motion"))
            statusParts.Add("Motion: " + (m.Parameter("Sensor.Motion").DecimalValue > 0 ? "Detected" : "None"));

        if (m.HasParameter("Meter.Watts"))
            statusParts.Add("Watts: " + Fmt(m.Parameter("Meter.Watts").DecimalValue, "W"));

        if (m.HasParameter("Meter.Watts.Hour"))
            statusParts.Add("Watthour: " + Fmt(m.Parameter("Meter.Watts.Hour").DecimalValue, "W/h"));

        if (m.HasParameter("Sensor.DoorWindow"))
            statusParts.Add("Door/Window: " + (m.Parameter("Sensor.DoorWindow").DecimalValue > 0 ? "Open" : "Closed"));

        // 3. ACTUATORS (Lights, Switches, Dimmer, Shutters)
        // Reports live state (ON/OFF/%) for the system status update
        if (m.HasParameter("Status.Level"))
        {
            var level = m.Parameter("Status.Level").DecimalValue;
            string state = (level > 0) ? "ON" : "OFF";

            // Append percentage for dimmers or color lights
            if (level > 0 && level <= 1) state = "ON"; // Standard binary
            else if (level > 1) state += $" ({level}%)";

            statusParts.Add("State: " + state);
        }

        // Final fallback to ensure the AI knows the device is reachable
        if (statusParts.Count == 0) statusParts.Add("Status: Online");

        return $"{m.Instance.Name}: {string.Join(", ", statusParts)}";
    }
}

public static class ChatContextPolicy
{
    public static readonly string[] Keys = { "devices", "widgets", "automationPrograms", "dashboards", "deepKnowledge" };
    public static JObject Normalize(JObject request)
    {
        request = request ?? new JObject();
        if (request.Properties().Any(p => p.Name != "version" && p.Name != "context"))
            throw new InvalidOperationException("Unknown context request field.");
        if (request["version"] != null && (request["version"].Type != JTokenType.Integer || (int)request["version"] != 1))
            throw new InvalidOperationException("Unsupported context contract version.");
        if (request["context"] != null && !(request["context"] is JObject))
            throw new InvalidOperationException("Context must be an object of boolean selections.");
        var selected = request["context"] as JObject ?? new JObject();
        if (selected.Properties().Any(p => !Keys.Contains(p.Name)))
            throw new InvalidOperationException("Unknown context option.");
        var normalized = new JObject();
        foreach (string key in Keys) {
            if (selected[key] != null && selected[key].Type != JTokenType.Boolean)
                throw new InvalidOperationException("Context selections must be booleans.");
            normalized[key] = selected[key] == null ? key == "devices" : (bool)selected[key];
        }
        return normalized;
    }
    public static object Describe() => new {
        version = 1,
        options = new[] {
            new { id = "devices", defaultEnabled = true, description = "Device directory, properties, states and available commands." },
            new { id = "widgets", defaultEnabled = false, description = "Widget directory and relevant component sources." },
            new { id = "automationPrograms", defaultEnabled = false, description = "Automation directory and relevant program sources." },
            new { id = "dashboards", defaultEnabled = false, description = "Dashboard structure and widget/module associations." },
            new { id = "deepKnowledge", defaultEnabled = false, description = "Relevant technical documentation and API references." }
        }
    };
    public static object Build(JObject request)
    {
        var context = Normalize(request);
        var prompt = new StringBuilder();
        prompt.AppendLine("CONTEXT SHARING PROFILE (application settings, not execution permissions):");
        prompt.AppendLine(Newtonsoft.Json.JsonConvert.SerializeObject(new { catalog = Describe(), selected = context }));
        prompt.AppendLine("A selected option permits the application to supply that category. Use only data actually supplied; selection alone does not prove data is present.");
        prompt.AppendLine("Do not assume knowledge of excluded information or invent device IDs, program IDs, widget paths, properties or dashboard names.");
        prompt.AppendLine("If the request needs missing context, explain why and propose the smallest useful selection. Continue when the supplied information is sufficient.");
        prompt.AppendLine("You cannot enable sharing yourself. Enabling requires an explicit user action and applies to subsequent requests.");
        prompt.AppendLine("Sharing information does not authorize creating, updating, executing or deleting objects. Execution mode and permissions are provided separately.");
        prompt.AppendLine("Information previously discussed may remain in the conversation. Never claim that disabling context retracts data already shared.");
        prompt.AppendLine("A future context proposal uses context_request: {options: [catalog option IDs], reason: a concise explanation}. It is a proposal, never an executable action.");
        return new {
            version = 1, context,
            profileKey = "context-v1:" + string.Concat(Keys.Select(k => (bool)context[k] ? "1" : "0")),
            prompt = prompt.ToString()
        };
    }
}

public sealed class AiSkillCatalog
{
    const int MaxBytes = 512 * 1024;
    const int MaxIncludes = 64;
    readonly string root;
    readonly Dictionary<string, string> handlers = new Dictionary<string, string> {
        ["homegenie-intent"] = "device-control",
        ["homegenie-automan"] = "automation",
        ["homegenie-widget"] = "widget-composite",
        ["homegenie-genie"] = "unified"
    };
    public AiSkillCatalog(string dataRoot) { root = Path.GetFullPath(Path.Combine(dataRoot, "ai", "skills")); }
    static void CheckName(string name) {
        if (name == null || name.Length > 64 || !System.Text.RegularExpressions.Regex.IsMatch(name, @"^[a-z0-9]+(?:-[a-z0-9]+)*$"))
            throw new InvalidOperationException("Invalid skill name.");
    }
    string SafeFile(string relative) {
        if (string.IsNullOrWhiteSpace(relative) || Path.IsPathRooted(relative) || relative.Contains('\\') || relative.Contains(':'))
            throw new InvalidOperationException("Invalid skill resource path.");
        var parts = relative.Split('/');
        if (parts.Any(p => p == "" || p == "." || p == "..")) throw new InvalidOperationException("Invalid skill resource path.");
        string full = root;
        // Reject symbolic links/junctions in the root and every requested component.
        for (var ancestor = new DirectoryInfo(root); ancestor != null; ancestor = ancestor.Parent)
            if (ancestor.Exists && (ancestor.Attributes & FileAttributes.ReparsePoint) != 0)
                throw new InvalidOperationException("Linked skill directories are not supported.");
        foreach (var part in parts) {
            full = Path.Combine(full, part);
            if ((File.Exists(full) || Directory.Exists(full)) && (File.GetAttributes(full) & FileAttributes.ReparsePoint) != 0)
                throw new InvalidOperationException("Linked skill resources are not supported.");
        }
        if (!File.Exists(full)) throw new InvalidOperationException("Skill resource not found: " + relative);
        return full;
    }
    string Read(string relative) {
        var path = SafeFile(relative);
        if (new FileInfo(path).Length > MaxBytes) throw new InvalidOperationException("Skill resource exceeds size limit.");
        return File.ReadAllText(path, new UTF8Encoding(false, true)).Replace("\r\n", "\n");
    }
    JObject Skill(string name) {
        CheckName(name);
        string text = Read(name + "/SKILL.md");
        var match = System.Text.RegularExpressions.Regex.Match(text, @"\A---\n([\s\S]*?)\n---(?:\n|$)");
        if (!match.Success) throw new InvalidOperationException("Missing YAML frontmatter: " + name);
        var yaml = new YamlDotNet.RepresentationModel.YamlStream();
        yaml.Load(new StringReader(match.Groups[1].Value));
        if (yaml.Documents.Count != 1 || !(yaml.Documents[0].RootNode is YamlDotNet.RepresentationModel.YamlMappingNode map))
            throw new InvalidOperationException("Invalid skill metadata: " + name);
        Func<YamlDotNet.RepresentationModel.YamlMappingNode, string, string> scalar = (node, key) => {
            if (!node.Children.TryGetValue(new YamlDotNet.RepresentationModel.YamlScalarNode(key), out var value)) return null;
            if (!(value is YamlDotNet.RepresentationModel.YamlScalarNode item)) throw new InvalidOperationException("Expected scalar: " + key);
            return item.Value;
        };
        string declaredName = scalar(map, "name"), description = scalar(map, "description");
        if (declaredName != name || string.IsNullOrWhiteSpace(description) || description.Length > 1024)
            throw new InvalidOperationException("Invalid name or description: " + name);
        var metadata = new JObject();
        if (map.Children.TryGetValue(new YamlDotNet.RepresentationModel.YamlScalarNode("metadata"), out var meta)) {
            if (!(meta is YamlDotNet.RepresentationModel.YamlMappingNode metaMap)) throw new InvalidOperationException("Invalid metadata: " + name);
            foreach (var pair in metaMap.Children) {
                if (!(pair.Key is YamlDotNet.RepresentationModel.YamlScalarNode k) || !(pair.Value is YamlDotNet.RepresentationModel.YamlScalarNode v))
                    throw new InvalidOperationException("Skill metadata must contain string values.");
                metadata[k.Value] = v.Value;
            }
        }
        string handler = (string)metadata["homegenie-handler"];
        bool registered = handler != null && handlers.TryGetValue(name, out var known) && handler == known;
        return new JObject { ["name"] = name, ["description"] = description, ["compatibility"] = scalar(map, "compatibility"),
            ["metadata"] = metadata, ["handler"] = handler, ["handlerRegistered"] = registered,
            ["body"] = text.Substring(match.Length) };
    }
    public JObject List() {
        var skills = new JArray(); var diagnostics = new JArray();
        if (Directory.Exists(root)) {
            foreach (var directory in Directory.GetDirectories(root).OrderBy(p => Path.GetFileName(p), StringComparer.Ordinal)) {
                string name = Path.GetFileName(directory);
                try {
                    var skill = Skill(name); skill.Remove("body"); skills.Add(skill);
                } catch (Exception ex) { diagnostics.Add(new JObject { ["name"] = name, ["message"] = ex.Message }); }
            }
        }
        return new JObject { ["version"] = 1, ["skills"] = skills, ["diagnostics"] = diagnostics };
    }
    public JObject Compose(JObject request) {
        if (request == null || request.Properties().Any(p => p.Name != "version" && p.Name != "template" && p.Name != "skills"))
            throw new InvalidOperationException("Unknown prompt composition field.");
        if (request["version"] != null && (request["version"].Type != JTokenType.Integer || (int)request["version"] != 1))
            throw new InvalidOperationException("Unsupported prompt composition version.");
        if (request["template"] != null && request["template"].Type != JTokenType.String)
            throw new InvalidOperationException("Template must be a string.");
        if (request["skills"] != null && !(request["skills"] is JArray)) throw new InvalidOperationException("Skills must be an array.");
        string template = (string)request["template"] ?? "";
        if (Encoding.UTF8.GetByteCount(template) > MaxBytes) throw new InvalidOperationException("Template exceeds size limit.");
        var completed = new HashSet<string>(StringComparer.Ordinal);
        var active = new HashSet<string>(StringComparer.Ordinal);
        var selected = new JArray(); var resources = new JArray();
        int includes = 0;
        Func<string, string> expand = null;
        Func<string, bool, string> include = (id, isSkill) => {
            string relative;
            if (isSkill) { CheckName(id); relative = id + "/SKILL.md"; }
            else {
                var parts = id.Split('/');
                if (parts.Length < 3 || parts[1] != "references" || !id.EndsWith(".md", StringComparison.Ordinal))
                    throw new InvalidOperationException("KB references must use skill-name/references/file.md.");
                CheckName(parts[0]); relative = id;
            }
            if (active.Contains(relative)) throw new InvalidOperationException("Circular prompt inclusion: " + relative);
            if (completed.Contains(relative)) return "";
            if (++includes > MaxIncludes) throw new InvalidOperationException("Too many prompt inclusions.");
            active.Add(relative);
            string content;
            if (isSkill) {
                var skill = Skill(id);
                selected.Add(new JObject { ["name"] = id, ["metadata"] = skill["metadata"], ["handler"] = skill["handler"], ["handlerRegistered"] = skill["handlerRegistered"] });
                content = (string)skill["body"];
            } else { content = Read(relative); resources.Add(relative); }
            string result = expand(content);
            active.Remove(relative); completed.Add(relative);
            return result;
        };
        expand = text => {
            var result = new StringBuilder();
            string fence = null;
            int bytes = 0;
            foreach (string line in text.Replace("\r\n", "\n").Split('\n')) {
                string value = line.Trim();
                string chunk;
                if (fence == null && (value.StartsWith("#use-skill", StringComparison.Ordinal) || value.StartsWith("#use-kb", StringComparison.Ordinal))) {
                    var match = System.Text.RegularExpressions.Regex.Match(value, @"^#use-(skill|kb)\s+(\S+)$");
                    if (!match.Success) throw new InvalidOperationException("Malformed prompt inclusion directive.");
                    chunk = include(match.Groups[2].Value, match.Groups[1].Value == "skill");
                } else {
                    chunk = line + "\n";
                    if (value.StartsWith("```", StringComparison.Ordinal) || value.StartsWith("~~~", StringComparison.Ordinal)) {
                        if (fence == null) fence = value.Substring(0, 3);
                        else if (value == fence) fence = null;
                    }
                }
                bytes += Encoding.UTF8.GetByteCount(chunk);
                if (bytes > MaxBytes) throw new InvalidOperationException("Composed prompt exceeds size limit.");
                result.Append(chunk);
            }
            return result.ToString();
        };
        // Explicit selections are translated into directives; this does not enable tools or actions.
        if (request["skills"] is JArray requested) {
            if (requested.Count > MaxIncludes || requested.Any(v => v.Type != JTokenType.String)) throw new InvalidOperationException("Invalid skill selection.");
            template += "\n" + string.Join("\n", requested.Select(v => "#use-skill " + (string)v));
        }
        string prompt = expand(template).TrimEnd('\n') + "\n";
        var fingerprintInput = new JObject { ["prompt"] = prompt, ["skills"] = selected, ["resources"] = resources }.ToString(Newtonsoft.Json.Formatting.None);
        string fingerprint;
        using (var hash = SHA256.Create()) fingerprint = BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(fingerprintInput))).Replace("-", "").ToLowerInvariant();
        return new JObject { ["version"] = 1, ["prompt"] = prompt, ["skills"] = selected, ["resources"] = resources, ["fingerprint"] = fingerprint };
    }
}

ProgramBlock.ScriptSource:
var inputModules = Modules.WithFeature(InstanceSegmentation);
var requestsPerSecond = Program.Option(YoloRequestsPerSecond);

// Show toggle icon for this algorithm in the NVR / Video widget
Program
    .Emit("NVR.Vision.Algorithm", InstanceSegmentation)     // feature to toggle "On" in order to enable this algo
    .Emit("NVR.Vision.Algorithm.Icon", "pattern");          // material symbol icon for the toggle button

// Restart program if configuration has been changed to apply new settings.
When.ModuleParameterChanged( (module, property) => {
    if (module.Instance == Program.Module && property.Name.StartsWith("ConfigureOptions."))
    {
        if (Program.IsRunning) Program.Restart();
        return true;
    }
    return true;
});

var yoloModelPath = Program.Option("Yolo.ModelPath")?.Value;
if (String.IsNullOrEmpty(yoloModelPath))
{
    Program.Notify($"Configure the path of YOLO 'segment' model (.onnx file). {OptionButtons}");
    Pause(5);
    return;
}

var breathe = () => {
    if (requestsPerSecond.DecimalValue > 0)
    {
        Pause(1D / requestsPerSecond.DecimalValue);
    }
    else
    {
        Pause(0.2); // default is 5 RPS max
    }
};

// For details about this implemention see
// *ML.net* and *YoloSharp* documentation


try
{
    var errorOccurred = false;
    using var detectPredictor = new YoloPredictor(yoloModelPath);
    while (Program.IsRunning)
    {
        if (inputModules.SelectedModules.Count == 0)
        {
            Pause(1);
            continue;
        }
        inputModules.Each((module) => {
            var data = module.Command("Camera.GetPicture").GetValue();
            if (data == null || ((byte[])data).Length == 0)
            {
                // I/O errors might occasionally occur and can be ignored
                return false;
            }
            try
            {
                var result = detectPredictor.Segment((byte[])data);
                //Console.WriteLine($"Result: {result}");
                //Console.WriteLine($"Speed:  {result.Speed}");
                if (result.Count() > 0)
                {
                    var output = new List<SegmentResult>();
                    // Emit "Sensor.ObjectDetect.Subject.Data" event if anything
                    // mathing the configured "TriggerDetect" list
                    // was detected in the scene.
                    string[] matchList = module
                        .Parameter( InstanceSegmentationTrigger )?.Value
                        .Split(',').Select(p => p.Trim())
                        .Where(x => !string.IsNullOrEmpty(x))
                        .ToArray();
                    if (matchList.Length > 0)
                    {
                        var filtered = new List<Compunet.YoloSharp.Data.Segmentation>();
                        foreach (var r in result)
                        {
                            var subject = r.Name.Name;
                            if (matchList.Contains(subject))
                            {
                                filtered.Add(r);
                            }
                        }
                        if (filtered.Count > 0)
                        {
                            if (module.Parameter(ObjectDetect).DecimalValue != filtered.Count)
                            {
                                module.Emit(ObjectDetect, filtered.Count);
                            }
                            else
                            {
                                // update value and timestamp only, do not emit event
                                module.Parameter(ObjectDetect).SetData(filtered.Count);
                            }
                            foreach (var r in filtered)
                            {
                                output.Add(new SegmentResult(){
                                    Result = r,
                                    Mask = ExtractAndApproximateContour(r.Mask, 100)
                                });
                                module.Emit(ObjectDetectSubject, r);
                            }
                        }
                        else if (module.Parameter(ObjectDetect).DecimalValue != 0 && module.Parameter(ObjectDetect).IdleTime > 5)
                        {
                            module.Emit(ObjectDetect, 0);
                        }
                    }
                    else
                    {
                        foreach (var r in result)
                        {
                            output.Add(new SegmentResult(){
                                Result = r,
                                Mask = ExtractAndApproximateContour(r.Mask, 100)
                            });
                        }
                    }

                    if (output.Count > 0)
                    {
                        // Emit json data for the video player (overlay data)
                        var jsonResults = JsonConvert.SerializeObject(output);
                        module.Emit(VideoPlayerWidgetOverlaySegment, jsonResults);
                    }

                }
            }
            catch (Exception e)
            {
                errorOccurred = true;
                //Console.WriteLine(e.Message);
            }
            if (errorOccurred)
            {
                errorOccurred = false;
                Pause(3);
            }
            else
            {
                breathe();
            }
            return false;
        });
        breathe();
    }
}
catch (Exception e)
{
    Program.Notify($"Error: {e.Message} {OptionButtons}");
    Pause(5);
    return;
}

ProgramBlock.ScriptContext:
#using Compunet.YoloSharp.Memory

const string
OptionButtons = "[program_configure,program_disable]",
YoloModelPath = "Yolo.ModelPath",
YoloRequestsPerSecond = "Yolo.RequestsPerSecond",
ForCameraInputType = "VideoInput,Sensor:Widget.DisplayModule=/homegenie/generic/(videoinput|camerainput)/",
InstanceSegmentation = "ML.InstanceSegmentation",
InstanceSegmentationTrigger = $"{InstanceSegmentation}.TriggerDetect",
ObjectDetect = "Sensor.ObjectDetect",
ObjectDetectSubject = "Sensor.ObjectDetect.Subject",
VideoPlayerWidgetOverlaySegment = "Widget.Data.VideoPlayer.Overlay.Segment";

public class SegmentResult
{
    public Compunet.YoloSharp.Data.Segmentation Result;
    public List<MaskPoint> Mask;
}

public class MaskPoint
{
    public float X;
    public float Y;
    public MaskPoint(float x, float y)
    {
        X = x;
        Y = y;
    }
}

public static List<MaskPoint> ExtractAndApproximateContour(BitmapBuffer r, int maxPoints = 25)
{
    var contour = ExtractContourPointsInternal(r);  // Get the initial contour

    if (contour.Count <= maxPoints)
    {
        return contour; // No need to approximate if already within the limit
    }

    // Implement a simple approximation by taking equally spaced points
    var approximatedContour = new List<MaskPoint>();
    double interval = (double)contour.Count / maxPoints;
    for (int i = 0; i < maxPoints - 1; i++)
    {
        int index = (int)Math.Round(i * interval); //Round for accuracy
        approximatedContour.Add(contour[index]); // Add existing point at the index
    }

    //Ensure the loop has the final item; If the last isn't added, add it
    if(approximatedContour.Last() != contour.Last()) {
            approximatedContour.Add(contour.Last());
    }

    return approximatedContour;
}


private static List<MaskPoint> ExtractContourPointsInternal(BitmapBuffer r)
{
    int height = r.Height;
    int width = r.Width;

    // Helper function to check if a pixel is a border pixel
    bool IsBorderPixel(BitmapBuffer mask, int x, int y)
    {
        if (x == 0 || x == width - 1 || y == 0 || y == height - 1)
        {
            return true;
        }

        return (mask[y, x - 1] > 0.9 != mask[y, x] > 0.9 ||
                mask[y, x + 1] > 0.9 != mask[y, x] > 0.9 ||
                mask[y - 1, x] > 0.9 != mask[y, x] > 0.9 ||
                mask[y + 1, x] > 0.9 != mask[y, x] > 0.9);
    }

    // Find all contour pixels
    var contourPixels = new List<MaskPoint>();
    for (int y = 0; y < height; y++)
    {
        for (int x = 0; x < width; x++)
        {
            if (r[y, x] > 0.9 && IsBorderPixel(r, x, y))
            {
                contourPixels.Add(new MaskPoint(x, y));
            }
        }
    }

    if (contourPixels.Count == 0)
    {
        return new List<MaskPoint>(); // Return empty list if no shape found
    }

    // Order the contour pixels (nearest neighbor approach)
    var contour = new List<MaskPoint>();
    var startPixel = contourPixels[0];
    contour.Add(startPixel);
    contourPixels.Remove(startPixel);

    var currentPixel = startPixel;

    while (contourPixels.Count > 0)
    {
        var nearestNeighbor = contourPixels
            .OrderBy(p => Math.Sqrt(Math.Pow(p.X - currentPixel.X, 2) + Math.Pow(p.Y - currentPixel.Y, 2))) // Euclidean distance
            .FirstOrDefault();

        if (nearestNeighbor == null)  // No more neighbors found
        {
            break;
        }

        contour.Add(nearestNeighbor);
        contourPixels.Remove(nearestNeighbor);
        currentPixel = nearestNeighbor;
    }

    return contour;
}

ProgramBlock.ScriptSetup:
// ===================================================================
// SETUP BLOCK - PROGRAM INITIALIZATION
// ===================================================================
// This block is executed once when the program is enabled.
// It is responsible for:
// 1. Loading the available models for the UI selection.
// 2. Registering the program as a system-wide AI Intent Handler.
// 3. Defining user-configurable options (tokens, model, prompt).
// 4. Linking the specific front-end chat widget.
// ===================================================================

// --- 1. PRE-SETUP CONFIGURATION DATA ---

// Load available GGUF models from models.yaml to populate the dropdown
var modelsList = LoadModelList(Path.Combine(Data.GetFolder(), CONFIG_FILE_NAME));
var models = string.Join(",", modelsList.Select(item => $"{ModelSelectionLabel(item.Value)}={item.Key}"));

// Path to the external markdown file for system instructions
var systemPromptFile = Path.Combine(Data.GetFolder(), "system_prompt.txt");
var modelsFile = Path.Combine(Data.GetFolder(), CONFIG_FILE_NAME);


// --- 2. PROGRAM SETUP DELEGATE ---

// Newly exposed automation actions require an explicit user opt-in.
var initialCapabilities=ReadChatSetting("AI.Chat.Capabilities")??new JObject{["deviceControl"]=true,["widgets"]=false};
if(initialCapabilities["automation"]==null || initialCapabilities["widgets"]==null) {
    if(initialCapabilities["automation"]==null)initialCapabilities["automation"]=false;
    if(initialCapabilities["widgets"]==null)initialCapabilities["widgets"]=false;
    Program.Parameter("AI.Chat.Capabilities").Value=initialCapabilities.ToString(Formatting.None);
}

Program.Setup(() => {

  Program
    // Implement the AI Intent Handler interface to allow system integration
    .Implements(
      "@AI:IntentHandler",
      API_URL,
      new {requests=new {version=1,generate=true,execute=true},chat=new {feedback=true,context=new[]{"devices","automationPrograms","widgets"},capabilities=new[]{"deviceControl","automation","widgets"}}}
    )

    // UI Options Definition:
    // - Response length limit (Max Tokens)
    // - Model selection dropdown (populated from models.yaml)
    // - System Instructions (Markdown editor linked to system_prompt.txt)
    .AddOption(OPTION_MODEL_FILE, "", "0. AI Model", $"select:{ models }")
    .AddOption(OPTION_SEND_CONTEXT_DATA, "On", "1. Share system and module context with the AI", "checkbox")
    .AddOption(OPTION_MODEL_TEMPERATURE, "0.4", "2. Creativity (0.0 = Precise, 2.0 = Creative)", "slider:0.0:2.0:0.05")
    .AddOption(OPTION_CONTEXT_SIZE, "8192", "3. AI Memory Capacity (Context Window)", "slider:1024:32768:1024")
    .AddOption(OPTION_MAX_TOKENS, "1536", "4. Response Length (Max Tokens)", "slider:64:4096:32")
    .AddOption(OPTION_MAX_TURNS, "10", "5. Chat Memory (Max Turns) (0 = no limit)", "slider:0:20:1")
    .AddOption(OPTION_SYSTEM_INSTRUCTIONS, "", "6. System Prompt (Instructions)", $"editor:file:{systemPromptFile}:markdown")
    .AddOption(OPTION_MODEL_LIST, "", "7. AI Model List", $"editor:file:{modelsFile}:yaml")

    // Assign the custom UI widget for the chat interface
    .UseWidget("custom/examples/local-ai-chat")
    .Emit("@AI:IntentHandler", API_URL); // notify widgets

});


// --- 3. EXECUTION ---

// Trigger the transition to the MAIN block
Program.Run();

ProgramBlock.ScriptSource:
Api.Handle("AI.Genies/Lailama/Request.Execute", input => ForwardBackgroundRequest(Api.Parse(input).Data, "940", "Execute", (route,data)=>Api.Call(route,data)));
Api.Handle("AI.Genies/Lailama/Request.Generate", input => ForwardBackgroundRequest(Api.Parse(input).Data, "940", "Generate", (route,data)=>Api.Call(route,data)));
Api.Handle("AI.Genies/Lailama/Request.Status", input => ForwardBackgroundRequest(Api.Parse(input).Data, "940", "Status", (route,data)=>Api.Call(route,data)));
Api.Handle("AI.Genies/Lailama/Request.Cancel", input => ForwardBackgroundRequest(Api.Parse(input).Data, "940", "Cancel", (route,data)=>Api.Call(route,data)));

// ===================================================================
// LOCAL LLM AUTOMATION PROGRAM (LLamaSharp Edition)
// ===================================================================
// This block manages the integration of a Local Language Model (GGUF)
// for home automation control within HomeGenie.
//
// Main Responsibilities:
// 1. Model download management via System DownloadManager.
// 2. LLamaSharp engine initialization (VRAM/RAM management).
// 3. Dynamic device inventory generation for the System Prompt.
// 4. Token streaming with smart buffering and artifact filtering.
// 5. Automatic execution of API commands extracted from AI responses.
// ===================================================================

// --- 1. CONFIGURATION AND STATE INITIALIZATION ---

var reconfigureRequired = false;
int maxMessages = (int)Program.Option(OPTION_MAX_TURNS).DecimalValue * 2;
var modelsFile = Path.Combine(Data.GetFolder(), CONFIG_FILE_NAME);

// Load model configurations and file paths
var modelsList = LoadModelList(modelsFile);
var selectedModel = Program.Option(OPTION_MODEL_FILE).Value;
var lastDefaultsModel = selectedModel;
Program.Emit("LLM.ModelInfo", modelsList.ContainsKey(selectedModel)
    ? JsonConvert.SerializeObject(new {modelsList[selectedModel].Name, modelsList[selectedModel].Status,
        modelsList[selectedModel].Requirements, modelsList[selectedModel].TestNotes}) : "");
string localModelFile = Path.Combine(Data.GetFolder(), selectedModel);



// Register event handler to trigger a restart if configuration options change.
When.ModuleParameterChanged((module, parameter) => {
  if (module.Instance == Program.Module && parameter.Name.StartsWith("ConfigureOptions.")) {
    if (parameter.Name.EndsWith($".{OPTION_MODEL_LIST}"))
    {
      // Update model list option in the UI
      modelsList = LoadModelList(modelsFile);
      var models = string.Join(",", modelsList.Select(item => $"{ModelSelectionLabel(item.Value)}={item.Key}"));
      models = $"select:{ models }";
      // IMPORTANT: update only if changed to prevent loop Emit <-> ModuleParameterChanged
      if (parameter.Value != models)
      {
        Program.Option(OPTION_MODEL_FILE).FieldType = models;
      }
    }
    else
    {
      if (parameter.Name == "ConfigureOptions." + OPTION_MODEL_FILE) {
        var defaults = LailamaModelDefaults.ForSelection(lastDefaultsModel, parameter.Value, modelsList);
        lastDefaultsModel = parameter.Value;
        foreach (var setting in defaults) Program.Emit(setting.Key, setting.Value);
        if (defaults.Count > 0) {
            var lines = new List<string>();
            foreach (var setting in defaults) {
                var label = setting.Key == "ConfigureOptions.ModelTemperature" ? "Temperature"
                    : setting.Key == "ConfigureOptions.MaxTokens" ? "Maximum output tokens" : "Context size";
                lines.Add(label + ": " + setting.Value);
            }
            Program.Notify("Lailama", JsonConvert.SerializeObject(new {
                Version = 1, Persistent = true, Presentation = "toast",
                Id = "model-defaults-" + Guid.NewGuid().ToString("N"),
                Title = "Lailama", Severity = "info",
                Message = "Model defaults applied for " + modelsList[parameter.Value].Name + ":\n"
                    + string.Join("\n", lines) + "\nYou can review these values in the model settings."
            }));
        }
      }
      reconfigureRequired = true;
    }
  }
  return true;
});



// Reset UI status fields
Program
  .Emit("LLM.Id", "")
  .Emit("Status.System.RamGb", GetTotalMemoryGB())
  .Emit(FIELD_STATUS_INIT, "NotConfigured");


// --- 2. API: DOWNLOAD MANAGEMENT ---
// These endpoints bridge the UI with the system's DownloadManager utility.

Api.Handle($"{Program.Module.Domain}/{Program.Module.Address}/DownloadStart", (p) => {
     var model = modelsList[selectedModel];
     Program.Emit(FIELD_STATUS_INIT, "Download").Emit(FIELD_DOWNLOAD, "Requested");
     var item = JsonConvert.SerializeObject(new {
         Name = model.Name,
         Url = model.Url,
         Path = Data.GetFolder()
     });
     Api.Call("System.Utility/DownloadManager/Enqueue", item);
     return new ResponseStatus(Status.Ok);

}).Handle($"{Program.Module.Domain}/{Program.Module.Address}/DownloadCancel", (p) => {
     Program.Emit(FIELD_DOWNLOAD, "Pending");
     var item = JsonConvert.SerializeObject(new { Id = Program.Parameter(FIELD_DOWNLOAD_ID)?.Value });
     Api.Call("System.Utility/DownloadManager/Delete", item);
     Program
      .Emit(FIELD_DOWNLOAD_ID, "")
      .Emit(Program.Option(OPTION_MODEL_FILE).Name, "");
     return new ResponseStatus(Status.Ok);

}).Handle($"{Program.Module.Domain}/{Program.Module.Address}/DownloadPause", (p) => {
    Program.Emit(FIELD_DOWNLOAD, "Paused");
    var item = JsonConvert.SerializeObject(new { Id = Program.Parameter(FIELD_DOWNLOAD_ID)?.Value });
    Api.Call("System.Utility/DownloadManager/Pause", item);
    return new ResponseStatus(Status.Ok);

}).Handle($"{Program.Module.Domain}/{Program.Module.Address}/DownloadResume", (p) => {
    var item = JsonConvert.SerializeObject(new { Id = Program.Parameter(FIELD_DOWNLOAD_ID)?.Value });
    Api.Call("System.Utility/DownloadManager/Resume", item);
    return new ResponseStatus(Status.Ok);
});


// --- 2.1 INFERENCE POST-PROCESSING HELPER METHOD (shared for using by other programs)
Api.Handle($"{Program.Module.Domain}/{Program.Module.Address}/Extract", (modelResponse) => {
    return ExtractResponse(ReadActionResponse(modelResponse));
}).Handle($"{Program.Module.Domain}/{Program.Module.Address}/Execute", (modelResponse) => {
    return ExecuteResponse(ReadActionResponse(modelResponse));
}).Handle($"{Program.Module.Domain}/{Program.Module.Address}/ExtractAndExecute", (modelResponse) => {
    return ExtractAndExecute(ReadActionResponse(modelResponse));
});


// --- 3. MODEL FILE VERIFICATION & MONITORING LOOP ---

if (!File.Exists(localModelFile)) {
  // Wait for finalization, not just 100% of bytes received into the .part file.
  while (Program.IsRunning)
  {
    if (reconfigureRequired) return;
    object response = Api.Call("System.Utility/DownloadManager/GetStatus", localModelFile);
    // The service can be temporarily unregistered during startup or a package update.
    // Keep the same polling loop alive; never restart the program or load a partial model.
    dynamic fileStatus = null;
    try {
      if (response is string statusJson && !string.IsNullOrWhiteSpace(statusJson))
        fileStatus = JObject.Parse(statusJson);
      else if (response is JObject statusObject) fileStatus = statusObject;
    } catch (Newtonsoft.Json.JsonException) {
      // An unavailable/incomplete status is transient. Pause below and try again.
    }

    if (fileStatus?.Success == true)
    {
      var task = fileStatus?.Data;
      if (task != null)
      {
        // Update UI with real-time download progress
        Program
          .Emit(FIELD_DOWNLOAD, task.Status.ToString())
          .Emit(FIELD_DOWNLOAD_ID, task.Id.ToString())
          .Emit(FIELD_DOWNLOAD_TASK, task.DestinationFilePath.ToString())
          .Emit(FIELD_DOWNLOAD_ERROR, task.ErrorMessage?.ToString() ?? "")
          .Emit(FIELD_DOWNLOAD_PROGRESS, task.ProgressPercentage.ToString("F2", CultureInfo.InvariantCulture));

        // The downloader closes and moves the file before reporting Completed.
        // Paused/Error tasks may also have 100% progress: keep them recoverable.
        if (string.Equals(task.Status?.ToString(), "Completed", StringComparison.OrdinalIgnoreCase)
            && File.Exists(localModelFile)) break;
      }
      else if (Program.Parameter(FIELD_DOWNLOAD_TASK)?.Value != localModelFile)
      {
        // No active task found for this file
        Program
          .Emit(FIELD_DOWNLOAD, "Pending")
          .Emit(FIELD_DOWNLOAD_ID, String.IsNullOrEmpty(selectedModel) ? "Pending" : "")
          .Emit(FIELD_DOWNLOAD_TASK, localModelFile)
          .Emit(FIELD_DOWNLOAD_PROGRESS, "0");
          if (modelsList.ContainsKey(selectedModel))
          {
            Program.Emit(FIELD_DOWNLOAD_REPOSITORY, modelsList[selectedModel].Repository);
          }
          else
          {
            Program.Emit(FIELD_DOWNLOAD_REPOSITORY, "");
          }
      }
    }

    if (reconfigureRequired) return;
    Pause(2); // Poll status every 2 seconds
  }

  if (!Program.IsRunning || reconfigureRequired) return;

  Program
    .Emit(FIELD_STATUS_ERROR, "")
    .Emit(FIELD_DOWNLOAD, "Complete")
    .Emit(FIELD_DOWNLOAD_PROGRESS, "100");

  // Continue into engine initialization in this run; no Setup/Main restart.
}
else if (Program.Parameter(FIELD_DOWNLOAD_TASK)?.Value != localModelFile)
{
  // File already exists; ensure UI state is consistent
  Program
    .Emit(FIELD_DOWNLOAD, "Complete")
    .Emit(FIELD_DOWNLOAD_ID, "")
    .Emit(FIELD_DOWNLOAD_PROGRESS, "100")
    .Emit(FIELD_DOWNLOAD_TASK, localModelFile);
}


// --- 4. LLM ENGINE INITIALIZATION (LLamaSharp) ---

Program
  .Emit("LLM.Id", selectedModel)
  .Emit(FIELD_STATUS_ERROR, "")
  .Emit(FIELD_STATUS_INIT, $"Starting");

var templateType = "";
var modelPath = localModelFile;

if (modelsList.ContainsKey(selectedModel)) {
  templateType = modelsList[selectedModel].Template;
} else {
  // ERROR: selected model not listed
  modelPath = "";
  Program
    .Emit(FIELD_DOWNLOAD_ID, "")
    .Emit(Program.Option(OPTION_MODEL_FILE).Name, "");
}

LailamaInferenceParams.AntiPrompts = LailamaStopPolicy.ForTemplate(templateType, LailamaInferenceParams.AntiPrompts);

LLamaWeights model = null;
LLamaContext context = null;
ChatSession session = null;
LLama.SessionState resetState = null;
var nativeLifetime = new LailamaNativeLifetime();
var sessionCache = new LailamaSessionCache();
Action<string> lifecycleLog = message => { try { Program.Log.Info(message); } catch { } };

// Release only after loading/inference has stopped. Native disposal itself runs in
// a background task, so a stalled native backend cannot indefinitely block shutdown.
var dispose = new Action(() => nativeLifetime.Stop(() => {
  session = null;
  try {
    if (resetState?.ContextState != null) {
      lifecycleLog("Lailama shutdown: disposing saved context state.");
      resetState.ContextState.Dispose(); resetState = null;
      lifecycleLog("Lailama shutdown: saved context state disposed.");
    }
  } finally {
  try {
    if (context != null) {
      lifecycleLog("Lailama shutdown: disposing context.");
      context.Dispose(); context = null;
      lifecycleLog("Lailama shutdown: context disposed.");
    }
  } finally {
    if (model != null) {
      lifecycleLog("Lailama shutdown: disposing model weights.");
      model.Dispose(); model = null;
      lifecycleLog("Lailama shutdown: model weights disposed.");
    }
  }
  }
}, lifecycleLog));

// Basic path validation
if (String.IsNullOrEmpty(modelPath))
{
  Program.Notify($"LLM model path not configured.[program_configure]").Emit(FIELD_STATUS_ERROR, "LLM model path not configured.").Emit(FIELD_STATUS_INIT, "Error");
}
else if (!File.Exists(modelPath))
{
  Program.Notify($"File not found: {modelPath}.[program_configure]").Emit(FIELD_STATUS_ERROR, $"File not found: {modelPath}").Emit(FIELD_STATUS_INIT, "Error");
}
else
{
  // Ensure cleanup on stop
  When.ProgramStopping(() => { dispose(); return true; });

  bool initializationFailed = false;
  CancellationTokenSource initializationCts;
  if (!nativeLifetime.TryBegin(out initializationCts)) return;
  try {
    initializationCts.Token.ThrowIfCancellationRequested();
    // Load Inference Parameters
    ApplyInferenceOptions(modelsList.ContainsKey(selectedModel) ? modelsList[selectedModel] : null);
    uint contextSize = (uint)Program.Option(OPTION_CONTEXT_SIZE).DecimalValue;

    lifecycleLog("Lailama configuration: temperature=" +
        ((DefaultSamplingPipeline)LailamaInferenceParams.SamplingPipeline).Temperature.ToString(System.Globalization.CultureInfo.InvariantCulture) +
        "; max output tokens=" + LailamaInferenceParams.MaxTokens + "; context=" + contextSize + "; history messages=" + maxMessages + ".");
    var parameters = GetOptimizedParams(modelPath, contextSize, modelsList.ContainsKey(selectedModel) ? modelsList[selectedModel] : null);
    lifecycleLog("Lailama initialization: loading weights; context=" + parameters.ContextSize +
        "; batch=" + parameters.BatchSize + "; microbatch=" + parameters.UBatchSize + "; GPU layers=" + parameters.GpuLayerCount + ".");

    // Load Model Weights and Context
    model = LLamaWeights.LoadFromFile(parameters);
    initializationCts.Token.ThrowIfCancellationRequested();
    lifecycleLog("Lailama initialization: weights loaded; creating context.");
    context = model.CreateContext(parameters);
    lifecycleLog("Lailama initialization: context created.");
    initializationCts.Token.ThrowIfCancellationRequested();

    var executor = new LailamaInteractiveExecutor(context);
    var chatHistory = new ChatHistory();

    // --- 5. SYSTEM PROMPT CONFIGURATION AND CHAT SESSION INIT ---
    var promptText = "";
    try { promptText = File.ReadAllText(Path.Combine(Data.GetFolder(), "system_prompt.txt")); } catch (Exception e) { }

    var systemPrompt = (string)Api.Call("System.Utility/ContextEngine/Render", promptText);

    // Clean initialization
    var systemMessage = new ChatHistory.Message(AuthorRole.System, (string)systemPrompt);
    chatHistory.Messages.Add(systemMessage);


    // SYNC: Fetch clean history from the System Service and sync LLamaSharp session
    string storeId = Program.Module.Address;
    try {
        var result = Api.Call("System.Utility/ChatHistory/GetContext", new { StoreId = storeId });
        dynamic unifiedlHistory = JArray.FromObject(result).ToObject<List<ChatMessage>>();

        if (unifiedlHistory != null) {

            // Re-populate with clean messages from service
            foreach(ChatMessage msg in unifiedlHistory) {
                var role = msg.Role == "user" ? AuthorRole.User : AuthorRole.Assistant;

                // --- FIX: Uso di un ciclo classico invece di LINQ .Select() ---
                var partsTextList = new List<string>();
                foreach (var part in msg.Parts) {
                    partsTextList.Add(part.Text);
                }
                string combinedText = string.Join("\n", partsTextList);
                chatHistory.Messages.Add(new ChatHistory.Message(role, combinedText));
            }
        }
    } catch (Exception ex) {
        Program.Log.Error("Sync error: " + ex.Message);
    }


    // Final session starts with the System Prompt already in history
    session = new ChatSession(executor, chatHistory);

    lifecycleLog("Lailama initialization: saving initial session state.");
    resetState = session.GetSessionState();
    session.LoadSession(resetState);

    // --- 6. WARMUP PHASE ---
    // Perform a dummy inference to pre-populate the KV cache and avoid latency on first use.
    Program.Emit(FIELD_STATUS_INIT, "WarmingUp");
    try {
        var warmupParams = new InferenceParams() { MaxTokens = 1 };
        var warmupCancellation = initializationCts;
        var warmup = Task.Run(async () => {
            await foreach (var token in session.ChatAsync(new ChatHistory.Message(AuthorRole.User, " "), warmupParams, cancellationToken: warmupCancellation.Token)) { }
        });
        try { warmup.GetAwaiter().GetResult(); }
        catch (ThreadInterruptedException) {
            // The host may interrupt Main while the native warmup is still unwinding.
            // Transfer ownership to the worker: never release its context prematurely.
            warmup.ContinueWith(_ => nativeLifetime.End(warmupCancellation), TaskScheduler.Default);
            initializationCts = null;
            throw;
        }
    } catch (ThreadInterruptedException) { throw; }
    catch (OperationCanceledException) when (nativeLifetime.IsStopping) { throw; }
    catch (Exception ex) {
        Program.Log.Warn($"Warmup warning: {ex}");
    }
    // Ready is emitted after chat APIs are registered.


    Api.Handle(API_URL+"/Provider.Text.Generate", input => {
        var data=Api.Parse(input).Data as IDictionary<string,object>;
        string id=data!=null && data.TryGetValue("requestId",out var identity)?identity as string:null;
        Func<string,string,string,object> outcome=(state,text,error)=>new Dictionary<string,object>{["version"]=1,["requestId"]=id,["state"]=state,["text"]=text,["error"]=error};
        if(data==null || !data.TryGetValue("version",out var version) || version is not int v || v!=1 || string.IsNullOrWhiteSpace(id) ||
            !data.TryGetValue("cancellationToken",out var token) || token is not CancellationToken cancellation ||
            !data.TryGetValue("systemPrompt",out var suppliedPrompt) || suppliedPrompt is not string instructions ||
            !data.TryGetValue("messages",out var suppliedMessages) || suppliedMessages is not JArray messages || messages.Count!=1 ||
            (string)messages[0]?["role"]!="user" || messages[0]?["parts"] is not JArray parts || parts.Count!=1 || parts[0]?["text"]?.Type!=JTokenType.String)
            return outcome("failed",null,"Invalid text generation request.");
        CancellationTokenSource lease;
        if(!nativeLifetime.TryBegin(out lease))return outcome("busy",null,"Local AI is busy or stopping.");
        return nativeLifetime.RunOwned<object>(lease, () => {
        try {
            using(var linked=CancellationTokenSource.CreateLinkedTokenSource(cancellation,lease.Token)) {
                linked.Token.ThrowIfCancellationRequested();
                // Reuse native memory under its exclusive lease. Invalidate chat reuse before replacing session contents.
                sessionCache.Invalidate();
                session.LoadSession(resetState);
                session.History.Messages.Clear();
                session.History.Messages.Add(new ChatHistory.Message(AuthorRole.System,instructions));
                string prompt=BuildUserPrompt(templateType,(string)parts[0]["text"]);
                if(context.Tokenize(instructions+"\n"+prompt,false,true).Length+LailamaInferenceParams.MaxTokens>=context.ContextSize)
                    return outcome("context_limit",null,"Background prompt and context exceed the local model context budget.");
                string reply="";
                ProcessAsync(session.ChatAsync(new ChatHistory.Message(AuthorRole.User,prompt),LailamaInferenceParams,cancellationToken:linked.Token),chunk=>reply+=chunk).GetAwaiter().GetResult();
                linked.Token.ThrowIfCancellationRequested();
                if(string.IsNullOrWhiteSpace(reply))return outcome("failed",null,"Local AI returned empty text.");
                // Conservative limit check: this backend does not expose a finish reason here.
                if(context.Tokenize(reply,false,true).Length>=LailamaInferenceParams.MaxTokens)
                    return outcome("output_limit",null,"Local AI reached its response budget.");
                reply=System.Text.RegularExpressions.Regex.Replace(reply,@"<think>[\s\S]*?(?:</think>|$)","",System.Text.RegularExpressions.RegexOptions.IgnoreCase).Trim();
                foreach(var marker in LailamaInferenceParams.AntiPrompts.Where(p=>p.StartsWith("<")))reply=reply.Replace(marker,"");
                if(string.IsNullOrWhiteSpace(reply))return outcome("failed",null,"Local AI returned no final text.");
                return outcome("completed",reply,null);
            }
        } catch(OperationCanceledException){return outcome("cancelled",null,null);}
          catch(Exception ex){lifecycleLog("Background text generation failed: "+ex.Message);return outcome("failed",null,"Local text generation failed. Check the provider logs.");}
        finally {
            sessionCache.Invalidate();
            if (!nativeLifetime.IsStopping) {session.LoadSession(resetState);session.History.Messages.Clear();}
        }
        }).GetAwaiter().GetResult();
    });

    Api.Handle(API_URL+"/Provider.Request.Execute", input => {
        var data=Api.Parse(input).Data as IDictionary<string,object>;
        if(data==null || !data.TryGetValue("cancellationToken",out var supplied) || supplied is not CancellationToken cancellation)
            throw new InvalidOperationException("Native execution request required.");
        CancellationTokenSource lease;
        if(!nativeLifetime.TryBegin(out lease))return new JObject{["version"]=1,["requestId"]=Convert.ToString(data["requestId"]),["state"]="busy",
            ["error"]="Local AI is busy or stopping.",["effectsMayHaveOccurred"]=false,["result"]=new JObject{["actions"]=new JArray()}};
        return nativeLifetime.RunOwned<object>(lease, () => {
        try {
            using(var linked=CancellationTokenSource.CreateLinkedTokenSource(cancellation,lease.Token)) {
                bool initialized=false;
                var request=new Dictionary<string,object>(data);
                request["providerId"]=Program.Module.Address;request["protocol"]="text";request["cancellationToken"]=linked.Token;
                request["template"]=File.ReadAllText(Path.Combine(Data.GetFolder(),"system_prompt.txt"));
                request["generate"]=new Func<JArray,string,object,IDictionary<string,object>>((messages,instructions,output)=> {
                    linked.Token.ThrowIfCancellationRequested();
                    if(!initialized) {
                        sessionCache.Invalidate();session.LoadSession(resetState);session.History.Messages.Clear();
                        session.History.Messages.Add(new ChatHistory.Message(AuthorRole.System,instructions));initialized=true;
                    }
                    string prompt=BuildUserPrompt(templateType,(string)messages[0]["parts"][0]["text"]);
                    var result=new Dictionary<string,object>{["version"]=1,["requestId"]=data["requestId"]};
                    string history=string.Join("\n",session.History.Messages.Select(m=>m.Content));
                    if(context.Tokenize(history+"\n"+prompt,false,true).Length+LailamaInferenceParams.MaxTokens>=context.ContextSize) {
                        result["state"]="context_limit";result["error"]="Local context budget exceeded.";return result;
                    }
                    string reply="";
                    ProcessAsync(session.ChatAsync(new ChatHistory.Message(AuthorRole.User,prompt),LailamaInferenceParams,cancellationToken:linked.Token),chunk=>reply+=chunk).GetAwaiter().GetResult();
                    linked.Token.ThrowIfCancellationRequested();
                    if(context.Tokenize(reply,false,true).Length>=LailamaInferenceParams.MaxTokens){result["state"]="output_limit";result["error"]="Local response budget exceeded.";return result;}
                    result["state"]="completed";result["text"]=reply;return result;
                });
                return Api.Call("System.Utility/AiGenie/Request.Run",request);
            }
        } finally {
            sessionCache.Invalidate();
            if (!nativeLifetime.IsStopping) {session.LoadSession(resetState);session.History.Messages.Clear();}
        }
        }).GetAwaiter().GetResult();
    });

    // --- 7. INFERENCE LOGIC AND TOKEN PROCESSING ---
    /**
      * Processes the user input, handles LLM inference, manages the token stream,
      * and synchronizes with the centralized Chat History Service.
      *
      * @param rawInput The clean text entered by the user.
      * @param synchronous Whether to wait for the full response before returning.
      * @return The full generated response (if synchronous), otherwise an empty string.
      */
    var processInput = new Func<string, bool, bool, bool, JObject, string>((rawInput, synchronous, sendContextData, noHistory, feedback) => {

        var telemetry = new ChatRequestMetrics(Api, storeId, !noHistory);


        CancellationTokenSource requestCts;
        if (!nativeLifetime.TryBegin(out requestCts))
            throw new InvalidOperationException("Local AI is busy or stopping. Wait for the current operation to finish.");

        if(feedback!=null)telemetry.SetFeedback(feedback);
        var process = new Func<bool, string>((sync) => {
            string failureThoughts="";
            try {
            requestCts.Token.ThrowIfCancellationRequested();
            // This accepted turn owns the operation lease; discard errors from prior turns.
            Program.Emit(FIELD_STATUS_ERROR, "");
            Func<object,JObject> readObject = value => value is string text ? JObject.Parse(text) : value == null ? null : JObject.FromObject(value);
            Func<string,JObject> storedSelection = name => {
                var property = Program.Module.Properties.FirstOrDefault(p => p.Name == name);
                string value = property == null ? null : Convert.ToString(property.Value);
                return string.IsNullOrWhiteSpace(value) ? null : JObject.Parse(value);
            };
            var selected = storedSelection("AI.Chat.Context") ?? new JObject();
            foreach (string key in new[]{"devices","widgets","automationPrograms","dashboards","deepKnowledge"}) {
                if (selected[key] != null && selected[key].Type != JTokenType.Boolean)
                    throw new InvalidOperationException("Invalid context selection: " + key);
                selected[key] = sendContextData && (selected[key]?.Value<bool>() ?? key == "devices");
            }
            // Only explicitly selected device/program context is supported by the local strategy.
            foreach(string key in new[]{"dashboards","deepKnowledge"}) selected[key]=false;
            var scope = new JObject { ["version"]=1, ["message"]=rawInput, ["context"]=selected,
                ["capabilities"]=LailamaCapabilityPolicy.Normalize(storedSelection("AI.Chat.Capabilities"),(bool)selected["devices"],(route,data)=>Api.Call(route,data)) };
            string localTemplate=File.ReadAllText(Path.Combine(Data.GetFolder(), "system_prompt.txt"));
            // Legacy placeholders are supplied by the scoped collector, not a second renderer.
            foreach(string placeholder in new[]{"%%AVAILABLE_DEVICES%%","%%SYSTEM_STATUS%%","%%CURRENT_TIME%%"})
                localTemplate=localTemplate.Replace(placeholder,"See ACTUALLY SUPPLIED CONTEXT below.");
            Func<string,int,JObject> textStep = (response,round) => {
                var lookupScope=(JObject)scope.DeepClone();
                lookupScope["context"]["widgets"]=(bool)scope["context"]["widgets"] && CurrentWidgetContextAllowed();
                var value=readObject(Api.Call("System.Utility/AiGenie/Text.Context.Step",new JObject{
                    ["version"]=1,["response"]=response,["round"]=round,["request"]=lookupScope,["template"]=localTemplate}));
                if(value!=null && (string)value["Status"]=="Error" && (string)value["errorKind"]=="contract")return value;
                if(value==null || (string)value["Status"]=="Error" || value["version"]?.Value<int>()!=1)
                    throw new InvalidOperationException((string)value?["Message"]??"AI Genie text context service is unavailable.");
                if((string)value["state"]=="context" && value["resources"] is JObject readResources) {
                    var accumulated=scope["resources"] as JObject??new JObject();
                    foreach(var resource in readResources.Properties()) {
                        var prior=accumulated[resource.Name] as JArray??new JArray();
                        accumulated[resource.Name]=new JArray(prior.Values<string>().Concat(((JArray)resource.Value).Values<string>()).Distinct());
                    }
                    scope["resources"]=accumulated;
                }
                return value;
            };
            var strategy=textStep("",0);
            if(strategy["instructions"]?.Type!=JTokenType.String)throw new InvalidOperationException("Update AI Genie before using local discovery.");
            localTemplate += "\n"+(string)strategy["instructions"];
            if(scope["capabilities"]["automation"].Value<bool>())localTemplate += "\n#use-skill homegenie-core\n"+(string)strategy["programInstructions"];
            if(scope["capabilities"]["widgets"].Value<bool>()) {
                if(strategy["widgetInstructions"]?.Type!=JTokenType.String)throw new InvalidOperationException("Update AI Genie before generating local widgets.");
                localTemplate += "\n"+(string)strategy["widgetInstructions"];
            }
            if(scope["capabilities"]["deviceControl"].Value<bool>()!=true)
                localTemplate += "\nDEVICE CONTROL DISABLED: device/parameter lookups are allowed when context sharing is enabled. Never emit api-call controls or parameter writes. Automation follows its separate capability. Ask the user to enable deviceControl for device actions; do not enable it yourself.";
            var prepared=readObject(Api.Call("System.Utility/AiGenie/Context.Prepare",new JObject{
                ["version"]=1,["template"]=localTemplate,["request"]=scope}));
            if(prepared==null || (string)prepared["Status"]=="Error" || prepared["systemPrompt"]?.Type!=JTokenType.String || prepared["profileKey"]?.Type!=JTokenType.String)
                throw new InvalidOperationException((string)prepared?["Message"]??"Local AI context is unavailable.");
            scope["context"]=prepared["context"].DeepClone();
            telemetry.ContextProfileKey=(string)prepared["profileKey"];
            if(feedback!=null && (string)feedback["contextProfileKey"]!=telemetry.ContextProfileKey)
                throw new ChatFeedbackProfileChangedException();
            if(feedback==null)telemetry.SaveUser(ChatMessage.Create("user",rawInput));
            var cleanHistory=new JArray();
            if(!noHistory) {
                var history=readObject(Api.Call("System.Utility/AiGenie/History.Read",new JObject{
                    ["version"]=1,["storeId"]=storeId,["profileKey"]=telemetry.ContextProfileKey,["projection"]="text"}));
                if(history==null || (string)history["contextProfileKey"]!=telemetry.ContextProfileKey || history["messages"] is not JArray entries)
                    throw new InvalidOperationException("Local AI history context is unavailable.");
                cleanHistory=(JArray)entries.DeepClone();
            }
            string sessionKey=LailamaSessionCache.Key(telemetry.ContextProfileKey,localTemplate,templateType,maxMessages);
            bool reuseSession=!noHistory && sessionCache.CanReuse(sessionKey,cleanHistory)
                && (maxMessages<=0 || session.History.Messages.Count<=maxMessages+1);
            // An interrupted/failed turn must never leave a reusable partial session.
            sessionCache.Invalidate();
            if(!reuseSession) {
                session.LoadSession(resetState);
                session.History.Messages.Clear();
                var contextHistory=LailamaContextSession.Rebuild(prepared,new JObject{
                    ["contextProfileKey"]=telemetry.ContextProfileKey,["messages"]=cleanHistory},maxMessages,(route,data)=>Api.Call(route,data));
                foreach(var item in contextHistory) {
                    string role=(string)item["role"];
                    string text=string.Join("\n",((JArray)item["parts"]).Select(p=>(string)p["text"]));
                    var nativeRole=role=="system"?AuthorRole.System:role=="user"?AuthorRole.User:AuthorRole.Assistant;
                    session.History.Messages.Add(new ChatHistory.Message(nativeRole,text));
                }
            }
            lifecycleLog("Lailama.Session "+new JObject{["requestId"]=telemetry.RequestId,["reused"]=reuseSession,
                ["historyMessages"]=cleanHistory.Count,["nativeMessages"]=session.History.Messages.Count}.ToString(Formatting.None));
            LailamaGenerationTrace trace=null;
            JObject programState=new JObject();
            bool artifactHandled=false;
            var coordinated=readObject(Api.Call("System.Utility/AiGenie/Conversation.Text.Run",new Dictionary<string,object> {
                ["version"]=1,["requestId"]=telemetry.RequestId,
                ["input"]=LailamaSessionCache.CurrentTurn((string)prepared["systemPrompt"],rawInput),
                ["cancellationToken"]=requestCts.Token,
                ["generate"]=new Func<string,int,IDictionary<string,object>>((roundInput,lookupRound)=> {
                    string templatedInput=BuildUserPrompt(templateType,roundInput);
            trace=new LailamaGenerationTrace(telemetry.RequestId,lookupRound,lifecycleLog);
            trace.Event("generation.start",()=> {
                string historyText=string.Join("\n",session.History.Messages.Select(m=>m.Content));
                int estimatedTokens=context.Tokenize(historyText+"\n"+templatedInput,false,true).Length;
                var values=LailamaGenerationTrace.State(executor.GetStateData());
                values["configuredContextSize"]=contextSize;
                values["nativeContextSize"]=context.ContextSize;
                values["historyMessages"]=session.History.Messages.Count;
                values["historyTextChars"]=historyText.Length;
                values["inputChars"]=templatedInput.Length;
                values["historyAndInputTextTokensEstimate"]=estimatedTokens;
                values["contextHeadroomTextEstimate"]=(long)context.ContextSize-estimatedTokens;
                values["maxOutputTokens"]=LailamaInferenceParams.MaxTokens;
                return values;
            });
            var generation = (IDictionary<string,object>)LailamaGenerationProvider.Generate(
                new Dictionary<string,object> {
                    ["version"]=1, ["requestId"]=telemetry.RequestId,
                    ["messages"]=JArray.FromObject(new[]{ChatMessage.Create("user",templatedInput)}),
                    ["cancellationToken"]=requestCts.Token
                }, (providerMessage,providerCancellation) => {
            // Send the templated input to the engine
            var sessionChat = session.ChatAsync(
                new ChatHistory.Message(AuthorRole.User, (string)providerMessage["parts"][0]["text"]),
                LailamaInferenceParams,
                cancellationToken: providerCancellation
            );

            string streamBuffer = "";
            string nativeReply = "";
            var technicalTags = LailamaInferenceParams.AntiPrompts.Where(x => x.StartsWith("<")).ToArray();
            var textStops = LailamaInferenceParams.AntiPrompts.Where(x => !x.StartsWith("<")).ToArray();
            string[] visualArtifacts = { "/assistant/avatar", "/avatar", "![avatar]", "![image]" };

            string nativeEndState="faulted";
            string observedAntiPrompt=null;
            try {
            ProcessAsync(sessionChat, (token) => {
                trace.Chunk(token);
                if (nativeLifetime.IsStopping || string.IsNullOrEmpty(token)) return;
                telemetry.FirstToken();
                streamBuffer += token;
                nativeReply += token;

                foreach (var art in visualArtifacts) if (streamBuffer.Contains(art)) streamBuffer = streamBuffer.Replace(art, "");
                foreach (var tag in technicalTags) if (streamBuffer.Contains(tag)) streamBuffer = streamBuffer.Replace(tag, "");
                foreach (var stop in textStops) {
                    if (streamBuffer.EndsWith(stop)) { observedAntiPrompt=stop; streamBuffer = ""; return; }
                }

                bool isPotentialDanger = false;
                foreach (var stop in textStops) if (stop.StartsWith(streamBuffer)) { isPotentialDanger = true; break; }

                if (!isPotentialDanger || streamBuffer.Length > 25) {
                    Program.Emit(FIELD_TOKENS_STREAM, streamBuffer);
                    streamBuffer = "";
                }
            }).GetAwaiter().GetResult();
            nativeEndState="stream-ended";
            } finally {
                trace.Event("generation.native.end",()=> {
                    var values=LailamaGenerationTrace.State(executor.GetStateData());
                    values["enumerationState"]=nativeEndState;
                    values["cancelled"]=providerCancellation.IsCancellationRequested;
                    values["stopping"]=nativeLifetime.IsStopping;
                    values["observedTextAntiPrompt"]=observedAntiPrompt;
                    values["rawReplyChars"]=nativeReply.Length;
                    values["finishReasonReported"]=false;
                    return values;
                });
            }

            if (!string.IsNullOrEmpty(streamBuffer)) {
                foreach (var tag in technicalTags) streamBuffer = streamBuffer.Replace(tag, "");
                if (!string.IsNullOrWhiteSpace(streamBuffer)) Program.Emit(FIELD_TOKENS_STREAM, streamBuffer);
            }


            // Some inference backends finish normally when cancelled. Never execute a partial reply.
            providerCancellation.ThrowIfCancellationRequested();

            return nativeReply;
            });
                    return generation;
                }),
                ["step"]=textStep,
                ["reset"]=new Action<string>(reason=>Program.Emit("LLM.TokenStream.Reset",reason)),
                ["contextCall"]=new Action<string>(path=>telemetry.ContextCalls.Add(path)),
                ["observe"]=new Action<string,JObject>((phase,details)=>trace?.Event(phase,()=>details)),
                ["execute"]=new Func<string,JObject>(reply=> {
                    var currentCapabilities=LailamaCapabilityPolicy.Normalize(ReadChatSetting("AI.Chat.Capabilities"),CurrentDeviceContextAllowed(),(route,data)=>Api.Call(route,data));
                    var programContext=(JObject)scope["context"].DeepClone();
                    programContext["automationPrograms"]=(bool)programContext["automationPrograms"] && CurrentProgramContextAllowed();
                    var programResult=readObject(Api.Call("System.Utility/AiGenie/Text.Artifact.Execute",new JObject {
                        ["version"]=1,["requestId"]=telemetry.RequestId,["response"]=reply,["state"]=programState,
                        ["capabilities"]=currentCapabilities,["context"]=programContext,["resources"]=(scope["resources"] as JObject)?.DeepClone()??new JObject()
                    }));
                    if(programResult==null || (string)programResult["Status"]=="Error")
                        throw new InvalidOperationException((string)programResult?["Message"]??"Text program service is unavailable.");
                    if(programResult["state"]?.Type!=JTokenType.String || (string)programResult["state"]!="not_program") {
                        if(programResult["state"] is not JObject nextProgramState || (string)programResult["requestId"]!=telemetry.RequestId)
                            throw new InvalidOperationException("Invalid program coordinator response.");
                        artifactHandled=true;
                        programState=(JObject)nextProgramState.DeepClone();
                        if((string)programResult["outcome"]=="context")return new JObject{["outcome"]="context",["resources"]=programResult["resources"].DeepClone(),["feedback"]=programResult["feedback"].DeepClone()};
                        telemetry.GenerationComplete();
                        telemetry.ActionsCompleted(0,(int)programResult["actionCalls"],(string)programResult["outcome"]=="completed"?0:1);
                        if((string)programResult["outcome"]=="repair")return new JObject{["outcome"]="repair",["feedback"]=programResult["feedback"].DeepClone(),["nextAttempt"]=programResult["nextAttempt"].DeepClone()};
                        string deploymentReply=(string)programResult["reply"];
                        Program.Emit("LLM.TokenStream.Reset","deployment");
                        Program.Emit(FIELD_TOKENS_STREAM,deploymentReply);
                        string finalThoughts=string.Concat(Regex.Matches(reply,@"<think>[\s\S]*?</think>",RegexOptions.IgnoreCase).Cast<Match>().Select(m=>m.Value+"\n"));
                        return new JObject{["reply"]=finalThoughts+deploymentReply,["outcome"]=programResult["outcome"].DeepClone(),["results"]=new JArray()};
                    }
                    if(!(bool)scope["context"]["devices"] && Regex.IsMatch(reply,@"```\s*api-call",RegexOptions.IgnoreCase))
                        throw new InvalidOperationException("Enable Devices context before controlling devices.");
            telemetry.GenerationComplete();
            var actionTimer = System.Diagnostics.Stopwatch.StartNew();
            var actionResults = ExecuteResponse(reply, telemetry.RequestId);
            telemetry.SetActionResults(actionResults);
            telemetry.ActionsCompleted(actionTimer.ElapsedMilliseconds, actionResults.Count, actionResults.Count(r => !r.Success));

            string verifiedReply=LailamaConfigurationActions.VerifiedReply(reply,JArray.FromObject(actionResults));
            bool configurationFailed=verifiedReply!=reply;
            if(configurationFailed) {
                Program.Emit("LLM.TokenStream.Reset","verification");
                // The UI has already retained this round's reasoning during reset.
                Program.Emit(FIELD_TOKENS_STREAM,Regex.Replace(verifiedReply,@"<think>[\s\S]*?</think>","",RegexOptions.IgnoreCase));
                reply=verifiedReply;
            }
                    return new JObject{["reply"]=reply,["results"]=JArray.FromObject(actionResults),["outcome"]=configurationFailed?"error":"completed"};
                })
            }));
            failureThoughts=coordinated?["thoughts"]?.Type==JTokenType.String?(string)coordinated["thoughts"]:"";
            requestCts.Token.ThrowIfCancellationRequested();
            if(coordinated?["cancelled"]?.Value<bool>()==true)throw new OperationCanceledException(requestCts.Token);
            if(coordinated==null || (string)coordinated["Status"]=="Error")
                throw new InvalidOperationException((string)coordinated?["Message"]??"Update AI Genie before using local conversation coordination.");
            if(coordinated["version"]?.Type!=JTokenType.Integer || (int)coordinated["version"]!=1 ||
                (string)coordinated["requestId"]!=telemetry.RequestId || coordinated["reply"]?.Type!=JTokenType.String ||
                coordinated["priorThoughts"]?.Type!=JTokenType.String || !new[]{"completed","error"}.Contains((string)coordinated["outcome"]))
                throw new InvalidOperationException("AI Genie returned an invalid text conversation result.");
            string fullReply=(string)coordinated["reply"],priorThoughts=(string)coordinated["priorThoughts"];
            bool configurationFailed=(string)coordinated["outcome"]=="error";
            var messageSegments = ExtractResponse(priorThoughts+fullReply);
            var modelResponse = new ChatMessage {
                Role = "model",
                Parts = messageSegments.Select(s => new MessagePart { Text = s }).ToList()
            };

            if (!noHistory)
            {
              telemetry.SaveReply(modelResponse,configurationFailed?"error":"completed");
              requestCts.Token.ThrowIfCancellationRequested();
              var committedHistory=(JArray)cleanHistory.DeepClone();
              committedHistory.Add(JObject.FromObject(ChatMessage.Create("user",rawInput)));
              committedHistory.Add(JObject.FromObject(modelResponse));
              if(artifactHandled || feedback!=null)sessionCache.Invalidate();
              else sessionCache.CommitTurn(sessionKey,committedHistory,coordinated);
              // The empty stream marker ends the whole request, after persistence.
              Program.Emit(FIELD_TOKENS_STREAM, "");
              Program.Emit("Widget.Refresh", "action_results");
            }

            if (noHistory) Program.Emit(FIELD_TOKENS_STREAM, "");
            return fullReply;
            } catch (OperationCanceledException) {
                if (!nativeLifetime.IsStopping) {
                    var recovery=RecoverFailedProgram(telemetry.RequestId);
                    if(recovery["attempted"]?.Value<bool>()==true)telemetry.ActionsCompleted(0,1,recovery["success"]?.Value<bool>()==true?0:1);
                    telemetry.Error(failureThoughts+"[STOPPED]\n"+(string)recovery["message"],"cancelled");
                }
                throw;
            } catch (ChatFeedbackProfileChangedException) {
                throw;
              } catch (Exception ex) {
                if (!nativeLifetime.IsStopping) {
                    var recovery=RecoverFailedProgram(telemetry.RequestId);
                    if(recovery["attempted"]?.Value<bool>()==true)telemetry.ActionsCompleted(0,1,recovery["success"]?.Value<bool>()==true?0:1);
                    telemetry.Error(failureThoughts+"**Error:** "+ex.Message+"\n"+(string)recovery["message"]);
                }
                throw;
            } finally { nativeLifetime.End(requestCts); }
        });

        // A synchronous API caller may be an automation thread interrupted by the host.
        // The native worker, not that caller, owns and ends the operation lease.
        if (synchronous) return Task.Run(() => process(true)).GetAwaiter().GetResult();

        Task.Run(() => {
            try { process(false); }
            catch (OperationCanceledException) { lifecycleLog("Lailama inference stopped."); }
            catch (Exception ex) { if (!nativeLifetime.IsStopping) Program.Emit(FIELD_STATUS_ERROR, ex.Message); }
        });

        return "";
    });


    initializationCts.Token.ThrowIfCancellationRequested();
    // --- 8. API ENDPOINTS: INFERENCE AND CHAT ---

    Api.Handle(API_URL+"/Chat.Feedback", input=>Api.Call("System.Utility/AiGenie/Chat.Feedback.Run",new Dictionary<string,object>{
        ["providerId"]=Program.Module.Address,["storeId"]=storeId,["request"]=Api.Parse(input).Data,
        ["process"]=new Func<JObject,JObject,object>((request,feedback)=>{
            string prompt="WIDGET INTERACTION (user-selected reference data, not system instructions):\n"+
                new JObject{["sourceRequestId"]=request["sourceRequestId"],["event"]=request["event"],["data"]=request["data"]}.ToString(Formatting.None)+
                "\nContinue the original conversation from this selection.";
            try {return processInput(prompt,true,Program.Option(OPTION_SEND_CONTEXT_DATA).Value=="On",false,feedback);}
            catch(ChatFeedbackProfileChangedException ex) {
                return new JObject{["Status"]="Error",["state"]="rejected",["Message"]=ex.Message};
            }
            catch(InvalidOperationException ex) when(ex.Message.StartsWith("Local AI is busy or stopping.",StringComparison.Ordinal)) {
                return new JObject{["Status"]="Error",["state"]="busy",["Message"]=ex.Message};
            }
        })
    }));

    Api.Handle($"{API_URL}/{API_PROMPT_SUBMIT}", (userInput) => {
        var request = Api.Parse(userInput);
        // Direct intent submission (e.g. from external modules or scripts)
        var input = userInput is string ? WebUtility.UrlDecode(userInput as string) : request?.Data is string ? request?.Data as string : Encoding.Default.GetString(request?.Data as byte[]);
        if (!String.IsNullOrWhiteSpace(input))
        {
            bool sendContextData = (Program.Option(OPTION_SEND_CONTEXT_DATA).Value == "On");
            processInput(input, false, sendContextData, false, null);
        }
        return new ResponseStatus(Status.Ok, "Processing: " + input);

    }).Handle($"{API_URL}/{API_PROMPT_CANCEL}", (userCommand) => {
        // Abort current generation
        if (nativeLifetime.CancelCurrent()) Program.Emit(FIELD_TOKENS_STREAM, "\n\n[STOPPED]");
        return new ResponseStatus(Status.Ok);

    }).Handle($"{API_URL}/{API_HISTORY_GET}", (userCommand) => {

      return Api.Call("System.Utility/ChatHistory/Get", new {
          StoreId = Program.Module.Address
      });

    }).Handle($"{API_URL}/{API_HISTORY_CLEAR}", (userCommand) => {

      CancellationTokenSource clearCts;
      if (!nativeLifetime.TryBegin(out clearCts)) return new ResponseStatus(Status.Error, "Local AI is busy or stopping.");
      try {
      sessionCache.Invalidate();
      var storeId = Program.Module.Address;
      Api.Call("System.Utility/ChatHistory/Clear", new { StoreId = storeId });
      if (session != null && resetState != null)
      {
          session.LoadSession(resetState);
          if (session.History.Messages.Count > 0)
          {
              session.History.Messages.Clear();
              //context.NativeHandle.MemoryClear(data: true);
              systemPrompt = (string)Api.Call("System.Utility/ContextEngine/Render", promptText);
              systemMessage = new ChatHistory.Message(AuthorRole.System, (string)systemPrompt);
              session.History.Messages.Add(systemMessage);
          }
      }
      Program.Log.Info($"[Module {storeId}] Cleared: Engine and Service are now empty.");
      return new ResponseStatus(Status.Ok);
      } finally { nativeLifetime.End(clearCts); }

    });

    Api.Handle($"{API_URL}/{API_HISTORY_REMOVE_AT}", (i) => {
    if (!int.TryParse(Api.Parse(i).OriginalRequest.Trim('/'), out var index) || index < 0)
        return (object)new ResponseStatus(Status.Error, "Invalid index");
    sessionCache.Invalidate();
    return Api.Call("System.Utility/ChatHistory/RemoveAt", new { StoreId = storeId, Index = index });
});
    Api.Handle($"{API_URL}/{API_HISTORY_EXPORT}", (p) => Api.Call("System.Utility/ChatHistory/Export", new { StoreId = storeId }));
    Api.Handle($"{API_URL}/{API_HISTORY_IMPORT}", (p) => Api.Call("System.Utility/ChatHistory/Import", new { StoreId = storeId, Data = (p as dynamic).Data }));

    initializationCts.Token.ThrowIfCancellationRequested();
    Program.Emit(FIELD_STATUS_INIT, "Ready");
    Program.Emit(FIELD_STATUS_ERROR, "");

  } catch (ThreadInterruptedException) { initializationFailed = true; throw; }
  catch (OperationCanceledException) when (nativeLifetime.IsStopping) {
    lifecycleLog("Lailama initialization cancelled during shutdown.");
  } catch (Exception e) {
    initializationFailed = true;
    lifecycleLog("Lailama initialization failed: " + e);
    if (!nativeLifetime.IsStopping) {
      Program.Notify($"ERROR: {e.Message} [program_configure]").Emit(FIELD_STATUS_ERROR, e.Message).Emit(FIELD_STATUS_INIT, "Error");
    } else lifecycleLog("Lailama initialization ended during shutdown: " + e);
  } finally {
    if (initializationCts != null) nativeLifetime.End(initializationCts);
    // End initialization before requesting cleanup, avoiding waiting on our own lease.
    // During interrupted warmup its worker retains the lease until it has really ended.
    if (initializationFailed) dispose();
  }
}

Program.Emit(FIELD_TOKENS_STREAM, "");

// --- 9. KEEP-ALIVE AND LIFECYCLE MONITORING ---

while (Program.IsRunning)
{
    if (reconfigureRequired)
    {
        dispose();
        // Do not load another model while old native resources are still in use.
        while (Program.IsRunning && !nativeLifetime.CleanupCompleted) Pause(1);
        return; // Exiting this loop triggers HomeGenie to reload the program block
    }
    Pause(1);
}

