/**
 * Loads the list of available models from a YAML configuration file.
 */
public static Dictionary<string, ModelInfo> LoadModelList(string configFilePath = CONFIG_FILE_NAME)
{
    string fullPath = configFilePath;
    try
    {
        string yaml = File.ReadAllText(fullPath);
        var deserializer = new DeserializerBuilder().Build();
        return deserializer.Deserialize<Dictionary<string, ModelInfo>>(yaml);
    }
    catch (Exception ex)
    {
        // Return empty dictionary if file is missing or corrupt
        return new Dictionary<string, ModelInfo>();
    }
}

