// Apply UI inference options to the shared sampler used by chat and background requests.
void ApplyInferenceOptions(ModelInfo profile = null) {
    double temperature = Program.Option(OPTION_MODEL_TEMPERATURE).DecimalValue;
    int maxTokens = (int)Program.Option(OPTION_MAX_TOKENS).DecimalValue;
    if (double.IsNaN(temperature) || double.IsInfinity(temperature) || temperature < 0 || temperature > 2)
        throw new ArgumentOutOfRangeException("ModelTemperature", "Temperature must be between 0 and 2.");
    if (maxTokens < 64 || maxTokens > 4096)
        throw new ArgumentOutOfRangeException("MaxTokens", "Response length must be between 64 and 4096 tokens.");
    var defaults = new DefaultSamplingPipeline { TopP = 0.95f, RepeatPenalty = 1.2f };
    var sampler = new DefaultSamplingPipeline {
        Temperature = (float)temperature,
        TopP = profile?.TopP ?? defaults.TopP,
        TopK = profile?.TopK ?? defaults.TopK,
        MinP = profile?.MinP ?? defaults.MinP,
        RepeatPenalty = profile?.RepeatPenalty ?? defaults.RepeatPenalty,
        PresencePenalty = profile?.PresencePenalty ?? defaults.PresencePenalty
    };
    LailamaInferenceParams.SamplingPipeline = sampler;
    LailamaInferenceParams.MaxTokens = maxTokens;
}

InferenceParams LailamaInferenceParams = new InferenceParams
{
    SamplingPipeline = new DefaultSamplingPipeline
    {
        TopP = 0.95f,
        RepeatPenalty = 1.2f
    },
    MaxTokens = 1024,

    // ANTI-PROMPTS (Stop Sequences)
    // This list prevents the model from "hallucinating" both sides of the conversation
