        "<|eot_id|>",           // Llama 3
        "<|eom_id|>",           // Llama 3 (End of Message)
        "<|end|>",              // Phi-3
        "<end_of_turn>",        // Gemma 2
        "<|end_of_sentence|>",  // DeepSeek
        "<|end_of_response|>",  // DeepSeek R1 / Reasoning models

        // --- GROUP 2: TURN-START MARKERS ---
