// Path to the external markdown file for system instructions
var systemPromptFile = Path.Combine(Data.GetFolder(), "gemini_system_prompt.txt");

Program.Setup(() => {
    // This method is used to register this program as a "AI intent handler"
    Program.Implements(
        "@AI:Genie",
        "AI.Genies/Gemini", new { requests = new { version = 1, generate = true, execute = true }, chat = new { requestVersion = 1, feedback = true, context = new [] { "devices", "widgets", "automationPrograms", "dashboards", "deepKnowledge" }, capabilities = new [] { "deviceControl", "automation", "widgets" } } }
    ).AddOption("ApiKey", "", "1. Google Gemini AI API key", "password")
     .AddOption("ModelId", "gemini-flash-latest", "2. Model ID", "text")
     .AddOption("SystemInstructions", "", "3. System Instructions", $"editor:file:{systemPromptFile}:markdown");
});

Program.Run();

ProgramBlock.ScriptSource:
Api.Handle("AI.Genies/Gemini/Request.Execute", input => ForwardBackgroundRequest(Api.Parse(input).Data, "933", "Execute", (route,data)=>Api.Call(route,data)));
Api.Handle("AI.Genies/Gemini/Request.Generate", input => ForwardBackgroundRequest(Api.Parse(input).Data, "933", "Generate", (route,data)=>Api.Call(route,data)));
Api.Handle("AI.Genies/Gemini/Request.Status", input => ForwardBackgroundRequest(Api.Parse(input).Data, "933", "Status", (route,data)=>Api.Call(route,data)));
Api.Handle("AI.Genies/Gemini/Request.Cancel", input => ForwardBackgroundRequest(Api.Parse(input).Data, "933", "Cancel", (route,data)=>Api.Call(route,data)));

// ===================================================================
// GEMINI WIDGET GENIE - WITH DEEP KNOWLEDGE & CACHING
// ===================================================================

string API_URL = "AI.Genies/Gemini";

string geminiApiKey = Program.Option("ApiKey").Value.Trim();
string geminiModelId = Program.Option("ModelId").Value.Trim();
// Structured requests obtain deep knowledge from the shared context service.
bool useDeepKnowledge = false;

if (geminiApiKey.Length != 39 || !geminiApiKey.StartsWith("AIzaSy") || string.IsNullOrEmpty(geminiModelId)) {
    Program.Emit("Status.Init", "NotConfigured");
} else {
    Program.Emit("Status.Init", "Ready");
}

bool reconfigureRequired = false;
When.ModuleParameterChanged((module, parameter) => {
  if (module.Instance == Program.Module && parameter.Name.StartsWith("ConfigureOptions.")) {
    reconfigureRequired = true;
  }
  // Generated-program Quit requests are handled by the shared AI Genie service.
  return true;
});

string storeId = Program.Module.Address;

// Cache Management Variables
string currentCacheName = "";
DateTime cacheExpiration = DateTime.MinValue;
string currentCacheContextHash = "";
Func<string, string> GetSlimmedXml = (filePath) => {
    if (!File.Exists(filePath)) return "";
    try {
        var doc = new System.Xml.XmlDocument();
        doc.Load(filePath);
        StringBuilder sb = new StringBuilder();
        var programs = doc.SelectNodes("//ProgramBlock");
        foreach (System.Xml.XmlNode pg in programs) {
//        foreach (System.Xml.XmlNode pg in doc.SelectNodes("//ProgramBlock[IsEnabled='true']")) {
            string name = pg.SelectSingleNode("Name")?.InnerText ?? "Unnamed";
            string address = pg.SelectSingleNode("Address")?.InnerText ?? "0";
            string setup = pg.SelectSingleNode("ScriptSetup")?.InnerText ?? "";
            string source = pg.SelectSingleNode("ScriptSource")?.InnerText ?? "";
            string context = pg.SelectSingleNode("ScriptContext")?.InnerText ?? "";

            if (string.IsNullOrWhiteSpace(source) && string.IsNullOrWhiteSpace(setup)) continue;

            sb.AppendLine($"--- PROGRAM: {address} NAME: {name} ---");
            if (!string.IsNullOrWhiteSpace(setup)) sb.AppendLine("[SETUP]\n" + setup);
            if (!string.IsNullOrWhiteSpace(source)) sb.AppendLine("[MAIN]\n" + source);
            if (!string.IsNullOrWhiteSpace(context)) sb.AppendLine("[CONTEXT]\n" + context);
            sb.AppendLine($"--- END PROGRAM: {address} ---\n");
        }
        return sb.ToString();
    } catch {
        return "Error slimming XML, fallback to raw read...";
    }
};
// --- FUNCTION: BUILD DEEP CONTEXT ---
Func<string> BuildContext = () => {
    var promptFile = Path.Combine(Data.GetFolder(), "gemini_system_prompt.txt");
    string context = "";
    context = AiPromptTemplate.Load(promptFile, (route, body) => Api.Call(route, body));

    if (useDeepKnowledge) {
        Program.Log.Info("Building Deep Knowledge Context...");
        StringBuilder sb = new StringBuilder();
        sb.AppendLine(context);
        sb.AppendLine("\n=======================================================");
        sb.AppendLine("HOMEGENIE SYSTEM SOURCE CODE (REFERENCE MATERIAL)");
        sb.AppendLine("=======================================================\n");

        // 1. Read programs.xml
        try {
            string hgRoot = Path.GetFullPath(Path.Combine(Data.GetFolder(), "..", ".."));
            string programsFile = Path.Combine("./", "programs.xml");
            if (File.Exists(programsFile)) {
                sb.AppendLine("--- FILE: programs.xml (C# Backend Logic) ---");
                sb.AppendLine(GetSlimmedXml(programsFile));
                sb.AppendLine("---------------------------------------------\n");
            }
        } catch (Exception ex) { Program.Log.Warn("Could not read programs.xml: " + ex.Message); }

        // 2. Read Widgets (HTML, CSS, JS)
        try {
            string programRoot = Path.GetFullPath(Path.Combine(Data.GetFolder(), "..", ".."));
            // Adjust the path to where your widgets actually are (e.g. html/widgets)
            string widgetsFolder = Path.Combine(programRoot, "widgets");

            if (Directory.Exists(widgetsFolder)) {
                var extensions = new[] { ".html", ".css", ".js" };
                var files = Directory.GetFiles(widgetsFolder, "*.*", SearchOption.AllDirectories)
                                     .Where(f => extensions.Contains(Path.GetExtension(f).ToLower()));

                foreach (var file in files) {
                    string relativePath = file.Replace(widgetsFolder, "").TrimStart(Path.DirectorySeparatorChar);
                    sb.AppendLine($"--- FILE: {relativePath} ---");
                    sb.AppendLine(File.ReadAllText(file));
                    sb.AppendLine($"--- END FILE: {relativePath} ---\n");
                }
            }
        } catch (Exception ex) { Program.Log.Warn("Could not read widgets: " + ex.Message); }

        context = sb.ToString();
    }
    return context;
};

// --- FUNCTION: CREATE CACHE ---
DateTime rateLimitResetTime = DateTime.MinValue;
bool isQuotaExceeded = false;
Func<string, bool> EnsureCache = (fullContext) => {
    if (!useDeepKnowledge) return false;
    string contextHash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(fullContext)));
    if (!string.IsNullOrEmpty(currentCacheName) && DateTime.UtcNow < cacheExpiration && currentCacheContextHash == contextHash) return true;

    Program.Log.Info("Uploading context to Gemini Cache...");
    var cacheUrl = $"https://generativelanguage.googleapis.com/v1beta/cachedContents?key={geminiApiKey}";

    var cachePayload = new {
        model = $"models/{geminiModelId}",
        system_instruction = new { parts = new[] { new { text = fullContext } } },
        ttl = "3600s"
    };

    try {
        var data = Net.WebService(cacheUrl)
            .AddHeader("Content-Type", "application/json")
            .Post(JsonConvert.SerializeObject(cachePayload))
            .GetData();

        if (data != null && data.name != null) {
            currentCacheName = data.name.ToString();
            cacheExpiration = DateTime.UtcNow.AddMinutes(55);
            currentCacheContextHash = contextHash;
            Program.Log.Info($"Cache created successfully: {currentCacheName}");
            return true;
        }
    } catch (Exception ex) {
        if (ex.Message.Contains("429")) {
            Program.Log.Warn("Gemini Cache Quota exceeded (429). Using standard mode (no cache).");
        } else {
            Program.Log.Warn($"Caching failed: {ex.Message}");
        }
        currentCacheName = "";
    }
    return false;
};

Func<object, JToken> contextToken = value => value is string text ? JToken.Parse(text) : JToken.FromObject(value);
Func<JObject, JObject> composeGeniePrompt = selected => {
    string template = File.ReadAllText(Path.Combine(Data.GetFolder(), "gemini_system_prompt.txt"));
    var result = contextToken(Api.Call("System.Utility/AiGenie/Prompt.Compose",
        new JObject { ["version"] = 1, ["template"] = template, ["capabilities"] = selected }));
    if (!(result is JObject composed) || (string)result["Status"] == "Error" || result["prompt"]?.Type != JTokenType.String)
        throw new InvalidOperationException((string)result?["Message"] ?? "AI Genie prompt preparation unavailable.");
    return composed;
};
Api.Handle(API_URL + "/Prompt.Preview", input => {
    try {
        var request = Api.Parse(input);
        object body = request?.Data;
        if (body is byte[] bytes) body = Encoding.UTF8.GetString(bytes);
        var envelope = body == null || body is string empty && string.IsNullOrWhiteSpace(empty) ? new JObject()
            : body is string text ? JObject.Parse(text) : JObject.FromObject(body);
        var selected = SharedCapabilityRequest("Capabilities.Normalize",envelope["capabilities"]);
        var composed = composeGeniePrompt(selected);
        return (object)new { version=1, capabilities=selected, fingerprint=composed["fingerprint"], skills=composed["skills"], resources=composed["resources"],
            allowedKinds=((JArray)SharedCapabilityRequest("Response.Schema",selected)["anyOf"]).Select(v=>(string)v["properties"]["kind"]["enum"][0]),
            promptBytes=Encoding.UTF8.GetByteCount((string)composed["prompt"]) };
    } catch (Exception ex) { return new { Status="Error",Message=ex.Message }; }
});
Api.Handle(API_URL + "/Capabilities.Describe", input => SharedCapabilityRequest("Capabilities.Describe"));

Func<string,JToken> storedChatSetting = name => {
    var property = Program.Module.Properties.FirstOrDefault(p => p.Name == name);
    if (property == null || string.IsNullOrWhiteSpace(Convert.ToString(property.Value))) return null;
    try { return JObject.Parse(Convert.ToString(property.Value)); }
    catch { throw new InvalidOperationException("Invalid persistent chat setting: " + name); }
};
Func<JObject, JObject> prepareScopedContext = input => {
    if (input["context"] == null) {
        var saved = storedChatSetting("AI.Chat.Context");
        if (saved != null) input["context"] = saved.DeepClone();
    }
    if (input["capabilities"] == null) {
        var saved = storedChatSetting("AI.Chat.Capabilities");
        if (saved != null) input["capabilities"] = saved.DeepClone();
    }
    // Preserve per-Genie defaults and its custom prompt; the service owns data collection.
    var result = contextToken(Api.Call("System.Utility/AiGenie/Context.Prepare", new JObject {
        ["version"] = 1, ["request"] = input,
        ["template"] = File.ReadAllText(Path.Combine(Data.GetFolder(), "gemini_system_prompt.txt"))
    }));
    if (!(result is JObject prepared) || (string)result["Status"] == "Error" || result["systemPrompt"]?.Type != JTokenType.String)
        throw new InvalidOperationException((string)result?["Message"] ?? "AI Genie context preparation unavailable.");
    return prepared;
};


Api.Handle(API_URL + "/Context.Preview", input => {
    try {
        var request = Api.Parse(input);
        object body = request?.Data ?? input;
        if (body is byte[] bytes) body = Encoding.UTF8.GetString(bytes);
        var envelope = body is string text ? JObject.Parse(text) : JObject.FromObject(body);
        var prepared = prepareScopedContext(envelope);
        return new { version = 1, profileKey = prepared["profileKey"], context = prepared["context"], included = prepared["included"],
            capabilities = prepared["capabilities"], promptBytes = Encoding.UTF8.GetByteCount((string)prepared["systemPrompt"]) };
    } catch (Exception ex) { return (object)new { Status = "Error", Message = ex.Message }; }
});

// ===================================================================
// API HANDLER: Process a new user message
// ===================================================================
// Provider generation is separate from the chat entry point and never takes geniePromptGate.
var providerLifetime = new CancellationTokenSource();
When.ProgramStopping(() => { providerLifetime.Cancel(); return true; });
Api.Handle(API_URL + "/Provider.Generate", input => GeminiGenerationProvider.Generate(Api.Parse(input).Data, (body, token) => {
    using (var linked = CancellationTokenSource.CreateLinkedTokenSource(token, providerLifetime.Token))
    using (var client = new System.Net.Http.HttpClient()) {
        client.Timeout = TimeSpan.FromSeconds(180);
        client.DefaultRequestHeaders.Add("x-goog-api-key", geminiApiKey);
        string json = JsonConvert.SerializeObject(body, new JsonSerializerSettings { NullValueHandling = NullValueHandling.Ignore });
        string url = $"https://generativelanguage.googleapis.com/v1beta/models/{geminiModelId}:generateContent";
        using (var content = new System.Net.Http.StringContent(json, Encoding.UTF8, "application/json"))
        using (var response = client.PostAsync(url, content, linked.Token).GetAwaiter().GetResult()) {
            if (!response.IsSuccessStatusCode) throw new System.Net.Http.HttpRequestException("Gemini HTTP error.", null, response.StatusCode);
            return JObject.Parse(response.Content.ReadAsStringAsync(linked.Token).GetAwaiter().GetResult());
        }
    }
}));
Api.Handle(API_URL+"/Provider.Text.Generate", input => {
    var request=Api.Parse(input).Data;
    // Reuse the transport adapter. It performs no chat/history/action processing.
    return Api.Call(API_URL+"/Provider.Generate",request);
});

Api.Handle(API_URL+"/Provider.Request.Execute", input => {
    var data=Api.Parse(input).Data as IDictionary<string,object>;
    if(data==null || !data.TryGetValue("cancellationToken",out var supplied) || supplied is not CancellationToken cancellation)
        throw new InvalidOperationException("Native execution request required.");
    using(var linked=CancellationTokenSource.CreateLinkedTokenSource(cancellation,providerLifetime.Token)) {
    var request=new Dictionary<string,object>(data);
    request["cancellationToken"]=linked.Token;
    request["providerId"]=Program.Module.Address;request["protocol"]="structured";
    request["template"]=File.ReadAllText(Path.Combine(Data.GetFolder(),"gemini_system_prompt.txt"));
    request["generate"]=new Func<JArray,string,object,IDictionary<string,object>>((messages,instructions,output)=> {
        if(reconfigureRequired || !Program.IsRunning)throw new InvalidOperationException("Gemini is restarting.");
        return Api.Call(API_URL+"/Provider.Generate",new Dictionary<string,object>{["version"]=1,["requestId"]=data["requestId"],
            ["messages"]=messages,["systemPrompt"]=instructions,["output"]=output,["cancellationToken"]=linked.Token}) as IDictionary<string,object>;
    });
    return Api.Call("System.Utility/AiGenie/Request.Run",request);
    }
});

Func<object, string, object, string, string> generateWithProvider = (messages, instructions, output, cache) => {
    var request = new Dictionary<string, object> {
        ["version"] = 1, ["requestId"] = Guid.NewGuid().ToString("N"), ["owner"] = Program.Module.Address,
        ["provider"] = "Gemini", ["messages"] = messages, ["systemPrompt"] = instructions, ["output"] = output,
        ["providerOptions"] = new Dictionary<string, object> { ["cachedContent"] = cache }
    };
    var result = Api.Call("System.Utility/AiGenie/Generate", request) as IDictionary<string, object>;
    if (result == null) throw new InvalidOperationException("AI Genie service is unavailable. Install and enable program 583.");
    if (!result.TryGetValue("version", out var version) || !(version is int) || (int)version != 1 ||
        !result.TryGetValue("requestId", out var identity) || !Equals(identity, request["requestId"]))
        throw new InvalidOperationException("AI Genie service returned an incompatible response.");
    string state = result.TryGetValue("state", out var status) ? status as string : null;
    if (state != "completed") {
        string error = result.TryGetValue("error", out var detail) ? detail as string : null;
        throw new InvalidOperationException(error ?? "AI generation ended with state: " + state);
    }
    string text = result.TryGetValue("text", out var completion) ? completion as string : null;
    if (string.IsNullOrWhiteSpace(text)) throw new InvalidOperationException("AI Genie returned an empty completion.");
    return text;
};

object geniePromptGate = new object();
Func<object, JObject, object> processGeniePrompt = (userCommand, feedback) =>
{
    lock (geniePromptGate) {
    JObject scopedRequest = null;
    JObject preparedContext = null;
    string msg;
    try {
        var request = Api.Parse(userCommand);
        object body = request?.Data ?? userCommand;
        if (body is byte[] bytes) body = Encoding.UTF8.GetString(bytes);
        if (body is string text) {
            if (text.TrimStart().StartsWith("{")) {
                try { var obj = JObject.Parse(text); if (obj["message"] != null) scopedRequest = obj; }
                catch (Newtonsoft.Json.JsonException) { }
            }
            msg = userCommand is string ? WebUtility.UrlDecode(text) : text;
        } else { scopedRequest = JObject.FromObject(body); msg = ""; }
        if (scopedRequest == null) scopedRequest = new JObject { ["version"] = 1, ["message"] = msg,
            ["context"] = new JObject { ["devices"] = true, ["widgets"] = false, ["automationPrograms"] = false, ["dashboards"] = false, ["deepKnowledge"] = false } };
        // Fill persistent selections before normalization; omitted feedback context is not a default-profile request.
        if (scopedRequest != null) {
            preparedContext = prepareScopedContext(scopedRequest);
            scopedRequest["context"] = preparedContext["context"].DeepClone();
            scopedRequest["capabilities"] = preparedContext["capabilities"].DeepClone();
            msg = (string)scopedRequest["message"];
            if(feedback!=null && (string)feedback["contextProfileKey"]!=(string)preparedContext["profileKey"])
                return new JObject{["Status"]="Error",["state"]="rejected",["Message"]="Chat context or capabilities changed since this presentation. Generate a new presentation."};
            // Old caches may include categories excluded by this profile. Never use them here.
            currentCacheName = ""; cacheExpiration = DateTime.MinValue;
        }
    } catch (Exception ex) { return new ResponseText("**Error:** " + ex.Message); }
    var telemetry = new ChatRequestMetrics(Api, Program.Module.Address);
    telemetry.ContextProfileKey = (string)preparedContext?["profileKey"];
    var userMessage = ChatMessage.Create("user", msg);
    if(feedback==null)telemetry.SaveUser(userMessage);else telemetry.SetFeedback(feedback);

    List<ChatMessage> payloadContents;
    try {
        var historyEnvelope=contextToken(Api.Call("System.Utility/AiGenie/History.Read",new JObject{
            ["version"]=1,["storeId"]=storeId,["profileKey"]=telemetry.ContextProfileKey,["projection"]="structured"}));
        if(historyEnvelope is not JObject || (string)historyEnvelope["Status"]=="Error" ||
            (string)historyEnvelope["contextProfileKey"]!=telemetry.ContextProfileKey || historyEnvelope["messages"] is not JArray historyMessages)
            throw new InvalidOperationException((string)historyEnvelope?["Message"]??"Provider history context is unavailable.");
        payloadContents=historyMessages.ToObject<List<ChatMessage>>();
    } catch(Exception ex) {return new ResponseText(telemetry.Error("**Error:** Unable to load the requested conversation context: "+ex.Message));}
    payloadContents.Add(userMessage);

    if (isQuotaExceeded && DateTime.UtcNow < rateLimitResetTime) {
        return new ResponseText(telemetry.Error($"**AI Temporarily Unavailable:** Rate limit reached (Error 429). Please try again in {Math.Ceiling((rateLimitResetTime - DateTime.UtcNow).TotalMinutes)} minutes."));
    }

    try
    {
    string fullContext = preparedContext != null ? (string)preparedContext["systemPrompt"] : BuildContext();
    bool hasCache = preparedContext == null && EnsureCache(fullContext);
    if (isQuotaExceeded) {
        return new ResponseText(telemetry.Error("**Quota Error:** Could not load the context. Please try again in a few minutes."));
    }

    var genConfig = new { temperature = 0.2, response_mime_type = "application/json", response_json_schema = SharedCapabilityRequest("Response.Schema",(JObject)preparedContext["capabilities"]) };

      var coordinated=contextToken(Api.Call("System.Utility/AiGenie/Conversation.Run",new Dictionary<string,object>{
          ["version"]=1,["requestId"]=telemetry.RequestId,["owner"]=Program.Module.Address,["provider"]="Gemini",
          ["messages"]=JArray.FromObject(payloadContents),["preparedContext"]=preparedContext,["request"]=scopedRequest,
          ["template"]=File.ReadAllText(Path.Combine(Data.GetFolder(),"gemini_system_prompt.txt")),
          ["systemPrompt"]=fullContext,["output"]=genConfig,["cache"]=hasCache?currentCacheName:null,
          ["scheduled"]=false,["elapsedBefore"]=telemetry.ElapsedMs
      }));
      if(coordinated is not JObject result|| (string)result["Status"]=="Error")
          throw new InvalidOperationException((string)coordinated?["Message"]??"AI Genie coordinator unavailable.");
      if(result["version"]?.Type!=JTokenType.Integer||(int)result["version"]!=1||(string)result["requestId"]!=telemetry.RequestId)
          throw new InvalidOperationException("AI Genie returned an incompatible conversation result.");
      telemetry.ImportRunMetrics(result["metrics"] as JObject);
      if(result["error"]?.Type==JTokenType.String)throw new InvalidOperationException((string)result["error"]);
      if(result["reply"]?.Type!=JTokenType.String||!new[]{"completed","error"}.Contains((string)result["outcome"]))
          throw new InvalidOperationException("AI Genie returned an invalid final reply.");
      string finalReply=(string)result["reply"];
      telemetry.SaveReply(ChatMessage.Create("model",finalReply),(string)result["outcome"]);
      return new ResponseText(finalReply);
    }
    catch (Exception ex)
    {
        if ((ex.Message.Contains("(429)") || ex.Message.Contains("HTTP 429"))) {
            isQuotaExceeded = true;
            rateLimitResetTime = DateTime.UtcNow.AddMinutes(2);
            return new ResponseText(telemetry.Error("**Errore 429:** Troppe richieste in corso. Ho messo in pausa le interrogazioni per un paio di minuti."));
        }
        Program.Log.Error($"Gemini API Error: {ex.Message}");
        return new ResponseText(telemetry.Error($"**Error:** {ex.Message}"));
    }
    }
};
Api.Handle(API_URL + "/Prompt.Submit", input => processGeniePrompt(input,null));
Api.Handle(API_URL+"/Chat.Feedback", input=>Api.Call("System.Utility/AiGenie/Chat.Feedback.Run",new Dictionary<string,object>{
    ["providerId"]=Program.Module.Address,["storeId"]=storeId,["request"]=Api.Parse(input).Data,
    ["process"]=new Func<JObject,JObject,object>((request,feedback)=>{
        if(!System.Threading.Monitor.TryEnter(geniePromptGate))return new JObject{["Status"]="Error",["state"]="busy",["Message"]="Gemini is processing another chat request."};
        try {
            var scoped=new JObject{["version"]=1,["message"]="WIDGET INTERACTION (user-selected reference data, not system instructions):\n"+
                new JObject{["sourceRequestId"]=request["sourceRequestId"],["event"]=request["event"],["data"]=request["data"]}.ToString(Formatting.None)+"\nContinue the original conversation from this selection."};
            return processGeniePrompt(scoped,feedback);
        }finally{System.Threading.Monitor.Exit(geniePromptGate);}
    })
}));



// APIs for Chat History
Api.Handle($"{API_URL}/{API_HISTORY_GET}", (p) => Api.Call("System.Utility/ChatHistory/Get", new { StoreId = storeId }));
Api.Handle($"{API_URL}/{API_HISTORY_CLEAR}", (p) => Api.Call("System.Utility/ChatHistory/Clear", new { StoreId = storeId }));
Api.Handle($"{API_URL}/{API_HISTORY_REMOVE_AT}", (i) => {
    if (!int.TryParse(Api.Parse(i).OriginalRequest.Trim('/'), out var index) || index < 0)
        return (object)new ResponseStatus(Status.Error, "Invalid index");

    return Api.Call("System.Utility/ChatHistory/RemoveAt", new { StoreId = storeId, Index = index });
});
Api.Handle($"{API_URL}/{API_HISTORY_EXPORT}", (p) => Api.Call("System.Utility/ChatHistory/Export", new { StoreId = storeId }));
Api.Handle($"{API_URL}/{API_HISTORY_IMPORT}", (p) => Api.Call("System.Utility/ChatHistory/Import", new { StoreId = storeId, Data = (p as dynamic).Data }));

// Previous Genies remain available; retirement is an explicit user action.
var legacyGenieIds = new Dictionary<int,string>{{930,"gemini-intent-handler"},{931,"gemini-widget-genie"},{932,"gemini-automan"}};
Func<JArray> legacyGenies = () => {
    var all=JArray.FromObject(Api.Call("HomeAutomation.HomeGenie/Automation/Programs.List"));
    return new JArray(all.OfType<JObject>().Where(p=>legacyGenieIds.ContainsKey((int)p["Address"])
        && (string)p["PackageInfo"]?["id"]==legacyGenieIds[(int)p["Address"]])
        .Select(p=>new JObject{["id"]=p["Address"],["name"]=p["Name"],["enabled"]=p["IsEnabled"]}));
};
Action publishLegacyNotice = () => {
    if(geminiApiKey.Length!=39 || !geminiApiKey.StartsWith("AIzaSy") || string.IsNullOrWhiteSpace(geminiModelId))return;
    var enabled=new JArray(legacyGenies().OfType<JObject>().Where(p=>p["enabled"]?.Value<bool>()==true));
    if(enabled.Count==0)return;
    var note=new JObject{["Version"]=1,["Persistent"]=true,["Id"]="gemini-genie-upgrade",["Title"]="Gemini Genie",
        ["Message"]="Gemini Genie includes device control, automation programs and widgets. Previous Genies remain available. You can disable them when you are ready; their settings and chat histories will be kept.",
        ["MessageKey"]="notification_genie_upgrade",["Severity"]="info",
        ["Details"]=string.Join("\n",enabled.OfType<JObject>().Select(p=>(string)p["id"]+" — "+(string)p["name"])),
        ["Actions"]=new JArray(new JObject{["Id"]="disable-legacy",["Label"]="Disable previous Genies",["LabelKey"]="notification_disable_genies",["Type"]="api",["Method"]="POST",
            ["Endpoint"]=API_URL+"/Legacy.Disable",["Idempotent"]=true,["Body"]=new JObject{["ProgramIds"]=new JArray(enabled.Select(p=>p["id"]))},
            ["Confirmation"]="Disable the listed previous Genies? Their settings and chat histories will be kept. You can enable them again at any time.",["ConfirmationKey"]="notification_disable_genies_confirm"})};
    Program.Notify("Gemini Genie",note.ToString(Formatting.None));
};
Api.Handle(API_URL+"/Legacy.Status", input=>legacyGenies());
Api.Handle(API_URL+"/Legacy.Disable", input=>{
    try {
        if(geminiApiKey.Length!=39||!geminiApiKey.StartsWith("AIzaSy")||string.IsNullOrWhiteSpace(geminiModelId))throw new InvalidOperationException("Configure Gemini Genie before disabling previous Genies.");
        var request=Api.Parse(input);var data=request?.Data;
        var body=data is byte[] bytes?JObject.Parse(Encoding.UTF8.GetString(bytes)):data is string text?JObject.Parse(text):JObject.FromObject(data??new{});
        var ids=body["ProgramIds"] as JArray;if(ids==null||ids.Count==0||ids.Count>3||ids.Any(id=>id.Type!=JTokenType.Integer||!legacyGenieIds.ContainsKey((int)id)))throw new InvalidOperationException("Expected only known previous Genie IDs.");
        var current=legacyGenies();var results=new JArray();
        foreach(int id in ids.Values<int>().Distinct()) {
            var old=current.OfType<JObject>().FirstOrDefault(p=>(int)p["id"]==id);
            if(old==null){results.Add(new JObject{["id"]=id,["state"]="not-present"});continue;}
            if(old["enabled"]?.Value<bool>()!=true){results.Add(new JObject{["id"]=id,["state"]="already-disabled"});continue;}
            try{Api.Call("HomeAutomation.HomeGenie/Automation/Programs.Disable/"+id);var after=legacyGenies().OfType<JObject>().FirstOrDefault(p=>(int)p["id"]==id);
                if(after?["enabled"]?.Value<bool>()==true)throw new InvalidOperationException("Program is still enabled.");
                results.Add(new JObject{["id"]=id,["state"]="disabled"});}
            catch(Exception e){results.Add(new JObject{["id"]=id,["state"]="failed",["error"]=e.Message});}
        }
        bool failed=results.Any(p=>(string)p["state"]=="failed");
        Program.Emit("AI.Genie.LegacyMigration",new JObject{["updatedAt"]=DateTime.UtcNow.ToString("O"),["results"]=results}.ToString(Formatting.None));
        return new JObject{["Status"]=failed?"Error":"Ok",["Message"]=failed?"Some previous Genies could not be disabled. Check the result and retry.":"Previous Genies disabled. Settings and chat histories were preserved.",["results"]=results};
    }catch(Exception e){return new ResponseStatus(Status.Error,e.Message);}
});
try{publishLegacyNotice();}catch(Exception e){Program.Log.Error("Gemini upgrade notification: "+e.Message);}

while (Program.IsRunning && !reconfigureRequired) {
    Pause(1);
}

