// Diagnostics stay in the history envelope, never in provider message objects.
// Thin in-process adapter; timing, metadata and persistence belong to AI Genie.
public class ChatRequestMetrics {
    readonly IDictionary<string,object> turn;
    string profile;
    public ChatRequestMetrics(dynamic api,string storeId,bool persist=true) {
        object result=api.Call("System.Utility/AiGenie/Turn.Create",new Dictionary<string,object> {
            ["version"]=1,["storeId"]=storeId,["persist"]=persist,["contextCalls"]=false
        });
        turn=result as IDictionary<string,object>;
        if(turn==null || !turn.TryGetValue("version",out var version) || version is not int v || v!=1 ||
            !turn.ContainsKey("saveReply") || turn["saveReply"] is not Action<object,string>)
            throw new InvalidOperationException("Update AI Genie: shared turn service unavailable.");
    }
    public string RequestId=>(string)turn["requestId"];
    public long ElapsedMs=>((Func<long>)turn["elapsed"])();
    public string ContextProfileKey {get=>profile;set {((Action<string>)turn["profile"])(value);profile=value;}}
    public JArray ContextCalls=>(JArray)turn["contextCalls"];
    public void FirstToken()=>((Action)turn["firstToken"])();
    public void GenerationComplete()=>((Action)turn["generationComplete"])();
    public void ActionsCompleted(long elapsedMs,int count,int failed)=>((Action<long,int,int>)turn["actionsCompleted"])(elapsedMs,count,failed);
    public void SetActionResults(object results)=>((Action<object>)turn["actionResults"])(results);
    public void ImportRunMetrics(JObject metrics)=>((Action<JObject>)turn["import"])(metrics);
    public object Snapshot(string outcome)=>((Func<string,object>)turn["snapshot"])(outcome);
    public void SetFeedback(JObject value)=>((Action<JObject>)turn["feedback"])(value);
    public void SaveUser(object message)=>((Action<object>)turn["saveUser"])(message);
    public void SaveReply(object message,string outcome="completed")=>((Action<object,string>)turn["saveReply"])(message,outcome);
    public string Error(string text,string outcome="error")=>((Func<string,string,string>)turn["error"])(text,outcome);
}

public static class AiPromptTemplate
{
    public static JObject Read(string file, Func<string, object, object> call)
    {
        string template = File.ReadAllText(file, new UTF8Encoding(false, true));
        // Old/custom prompt files remain valid and do not require a catalog service.
        if (!System.Text.RegularExpressions.Regex.IsMatch(template, @"(?m)^\s*#use-(?:skill|kb)(?:\s|$)")) {
            string hash;
            using (var sha = SHA256.Create()) hash = BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(template))).Replace("-", "").ToLowerInvariant();
            return new JObject { ["version"] = 1, ["prompt"] = template, ["skills"] = new JArray(), ["resources"] = new JArray(), ["fingerprint"] = hash };
        }
        object raw = call("System.Utility/ContextEngine/Prompt.Compose", new { version = 1, template });
        if (raw == null) throw new InvalidOperationException("Prompt composition is unavailable; update Context Engine and install the shared skills.");
        JToken result = raw is string text ? JToken.Parse(text) : JToken.FromObject(raw);
        if (result["Status"]?.ToString() == "Error") throw new InvalidOperationException("Prompt composition failed: " + result["Message"]);
        if (!(result is JObject composed) || composed["version"]?.Type != JTokenType.Integer || (int)composed["version"] != 1
            || composed["prompt"]?.Type != JTokenType.String || string.IsNullOrWhiteSpace((string)composed["prompt"])
            || !(composed["skills"] is JArray) || !(composed["resources"] is JArray) || composed["fingerprint"]?.Type != JTokenType.String)
            throw new InvalidOperationException("Prompt composition returned an invalid response.");
        return composed;
    }
    public static string Load(string file, Func<string, object, object> call) => (string)Read(file, call)["prompt"];
    public static object Summary(JObject composed) => new {
        version = 1, fingerprint = (string)composed["fingerprint"],
        skills = composed["skills"], resources = composed["resources"],
        promptBytes = Encoding.UTF8.GetByteCount((string)composed["prompt"])
    };
}

// Provider adapter: defaults and persisted selections remain owned by this Genie.
public JObject SharedCapabilityRequest(string operation, JToken selected = null) {
    var input=new JObject{["version"]=1};
    if(selected!=null)input["capabilities"]=selected.DeepClone();
    object raw=Api.Call("System.Utility/AiGenie/"+operation,input);
    var result=raw as JObject ?? (raw is string text?JToken.Parse(text) as JObject:raw==null?null:JToken.FromObject(raw) as JObject);
    if(result==null || (string)result["Status"]=="Error")throw new InvalidOperationException((string)result?["Message"]??"Update AI Genie: capability service unavailable.");
    return result;
}
// Provider-only transport mapping: no history, context lookup or action execution.
public static class GeminiGenerationProvider {
    public static object Generate(object payload, Func<object, CancellationToken, JObject> send) {
        var request = payload as IDictionary<string, object>;
        string id = request != null && request.TryGetValue("requestId", out var identity) ? identity as string : null;
        Func<string, string, string, object> result = (state, text, error) => new Dictionary<string, object> {
            ["version"] = 1, ["requestId"] = id, ["state"] = state, ["text"] = text, ["error"] = error };
        if (request == null || !request.TryGetValue("version", out var version) || !(version is int) || (int)version != 1 ||
            string.IsNullOrWhiteSpace(id) || !request.TryGetValue("messages", out var messages) || messages == null ||
            !request.TryGetValue("cancellationToken", out var token) || !(token is CancellationToken))
            return result("failed", null, "Invalid Gemini provider request.");
        var cancellation = (CancellationToken)token;
        try {
            cancellation.ThrowIfCancellationRequested();
            var body = new Dictionary<string, object> { ["contents"] = messages };
            if (request.TryGetValue("output", out var output) && output != null) body["generationConfig"] = output;
            var options = request.TryGetValue("providerOptions", out var supplied) ? supplied as IDictionary<string, object> : null;
            string cache = options != null && options.TryGetValue("cachedContent", out var cached) ? cached as string : null;
            if (!string.IsNullOrWhiteSpace(cache)) body["cached_content"] = cache;
            else if (request.TryGetValue("systemPrompt", out var prompt) && prompt is string instructions)
                body["system_instruction"] = new { parts = new[] { new { text = instructions } } };
            JObject data = send(body, cancellation);
            cancellation.ThrowIfCancellationRequested();
            var candidate = (data?["candidates"] as JArray)?.FirstOrDefault() as JObject;
            string finish = (string)candidate?["finishReason"];
            if (finish == "MAX_TOKENS") return result("output_limit", null, "Gemini reached its output limit.");
            if (finish != "STOP") return result("failed", null, "Gemini returned an empty, blocked or incomplete response.");
            var parts = candidate?["content"]?["parts"] as JArray;
            string text = parts == null ? "" : string.Concat(parts.OfType<JObject>()
                .Where(p => p["thought"]?.Value<bool>() != true && p["text"]?.Type == JTokenType.String)
                .Select(p => (string)p["text"]));
            if (string.IsNullOrWhiteSpace(text)) return result("failed", null, "Gemini returned an empty completion.");
            return result("completed", text, null);
        } catch (OperationCanceledException) {
            return cancellation.IsCancellationRequested ? result("cancelled", null, null) : result("failed", null, "Gemini generation timed out.");
        } catch (System.Net.Http.HttpRequestException ex) {
            return result("failed", null, ex.StatusCode.HasValue ? "Gemini returned HTTP " + (int)ex.StatusCode.Value + "." : "Gemini transport failed.");
        } catch (Exception) { return result("failed", null, "Gemini provider generation failed."); }
    }
}

public object ForwardBackgroundRequest(object payload,string providerId,string operation,Func<string,object,object> call) {
    try {
        if(payload is byte[] bytes)payload=Encoding.UTF8.GetString(bytes);
        var request=payload as JObject ?? (payload is string text?JObject.Parse(text):payload==null?null:JObject.FromObject(payload));
        if(request==null || request["providerId"]!=null && (string)request["providerId"]!=providerId)
            throw new InvalidOperationException("Provider does not match this endpoint.");
        request=(JObject)request.DeepClone();request["providerId"]=providerId;
        return call("System.Utility/AiGenie/Request."+operation,request);
    } catch(Exception) {return new JObject{["version"]=1,["state"]="failed",["error"]="Invalid request or AI Genie service unavailable."};}
}
